const DATA_2020=[{"id":"2020-1-A","t":"2020 1회 A형","q":[{"n":1,"s":1,"a":3,"p":"다음 중 사운드의 압축 및 복원과 관련된 기술에 해당하지 않는 것은?","c":["FLAC","AIFF","H.264","WAV"],"id":"2020-1-A","e":"2020 1회 A형"},{"n":2,"s":1,"a":2,"p":"다음 중 컴퓨터 게임이나 컴퓨터 기반 훈련과 같이 사용자 와의 상호작용을 통해 진행 상황을 제어하는 멀티미디어의 특징을 나타내는 용어는?","c":["선형 콘텐츠","비선형 콘텐츠","VR 콘텐츠","4D 콘텐츠"],"id":"2020-1-A","e":"2020 1회 A형"},{"n":3,"s":1,"a":3,"p":"다음 중 정보 보안을 위한 비밀키 암호화 기법에 대한 설명으로 옳지 않은 것은?","c":["비밀키 암호화 기법의 안전성은 키의 길이 및 키의 비밀성 유지 여부에 영향을 많이 받는다.","암호화와 복호화 시 사용하는 키가 동일한 암호화 기법 이다.","복잡한 알고리즘으로 인해 암호화와 복호화 속도가 느리다.","사용자가 증가할 경우 상대적으로 관리해야 할 키의 수가 많아진다."],"id":"2020-1-A","e":"2020 1회 A형"},{"n":4,"s":1,"a":3,"p":"다음 중 분산 서비스 거부 공격(DDos)에 관한 설명으로 옳은 것은?","c":["네트워크 주변을 돌아다니는 패킷을 엿보면서 계정과 패스워드를 알아내는 행위","검증된 사람이 네트워크를 통해 데이터를 보낸 것처럼 데이터를 변조하여 접속을 시도하는 행위","여러 대의 장비를 이용하여 특정 서버에 대량의 데이터를 집중적으로 전송함으로써 서버의 정상적인 동작을 방해 하는 행위","키보드의 키 입력시 캐치 프로그램을 사용하여 ID나 암호 정보를 빼내는 행위"],"id":"2020-1-A","e":"2020 1회 A형"},{"n":5,"s":1,"a":2,"p":"다음 중 VoIP에 대한 설명으로 옳지 않은 것은?","c":["인터넷 IP 기술을 사용한 디지털 음성 전송 기술이다.","원거리 통화 시 PSTN(public switched telephone network) 보다는 요금이 높지만 일정 수준의 통화 품질이 보장된다.","기존 회선교환 방식과 달리 네트워크를 통해 음성을 패킷형태로 전송한다.","보컬텍(VocalTec)사의 인터넷폰으로 처음 소개되었으며, PC to PC, PC to Phone, Phone to Phone 방식으로 발전하였다."],"id":"2020-1-A","e":"2020 1회 A형"},{"n":6,"s":1,"a":2,"p":"다음 중 대량의 데이터 안에서 일정한 패턴을 찾아내고, 이로부터 가치 있는 정보를 추출해내는 기술을 의미하는 것은?","c":["데이터 웨어하우스(Data Warehouse)","데이터 마이닝(Data Mining)","데이터 마이그레이션(Data Migration)","메타데이터(Metadata)"],"id":"2020-1-A","e":"2020 1회 A형"},{"n":7,"s":1,"a":4,"p":"다음 중 네트워크 프로토콜(Protocol)의 기능에 해당하지 않는 것은?","c":["패킷 수를 조정하는 흐름 제어 기능","송/수신기를 같은 상태로 유지하는 동기화 기능","데이터 전송 도중에 발생하는 에러 검출 기능","네트워크 기반 하드웨어 연결문제 해결 기능"],"id":"2020-1-A","e":"2020 1회 A형"},{"n":8,"s":1,"a":4,"p":"다음 중 인터넷 서버까지의 경로를 추적하는 명령어인 ‘Tracert’의 실행 결과에 관한 설명으로 옳지 않은 것은?","c":["IP 주소, 목적지까지 거치는 경로의 수, 각 구간 사이의 데이터 왕복 속도를 확인할 수 있다.","특정 사이트가 열리지 않을 때 해당 서버가 문제인지 인터넷 망이 문제인지 확인할 수 있다.","인터넷 속도가 느릴 때 어느 구간에서 정체를 일으키는지 확인할 수 있다.","현재 자신의 컴퓨터에 연결된 다른 컴퓨터의 IP 주소나 포트 정보를 확인할 수 있다."],"id":"2020-1-A","e":"2020 1회 A형"},{"n":9,"s":1,"a":2,"p":"다음 중 IPv6 주소에 관한 설명으로 옳지 않은 것은?","c":["16비트씩 8부분으로 총 128비트로 구성된다.","각 부분은 10진수로 표현되며, 세미콜론(;)으로 구분한다.","주소체계는 유니캐스트, 멀티캐스트, 애니캐스트로 나누어진다.","실시간 흐름 제어로 향상된 멀티미디어 기능을 지원한다."],"id":"2020-1-A","e":"2020 1회 A형"},{"n":10,"s":1,"a":3,"p":"다음 중 객체지향 프로그래밍 특징으로 옳은 것은?","c":["객체에 대하여 절차적 프로그래밍의 장점을 사용할 수 있다.","객체지향 프로그램은 주로 인터프리터 번역 방식을 사용한다.","객체지향 프로그램은 코드의 재사용과 유지보수가 용이 하다.","프로그램의 구조와 절차에 중점을 두고 작업을 진행한다."],"id":"2020-1-A","e":"2020 1회 A형"},{"n":11,"s":1,"a":3,"p":"다음 중 ASCII 코드에 대한 설명으로 옳지 않은 것은?","c":["3개의 Zone 비트와 4개의 Digit 비트로 하나의 문자를 표현한다.","데이터 통신용으로 사용하며, 128가지 문자를 표현할 수 있다.","2비트의 에러 검출 및 1비트의 에러 교정 비트를 포함 한다.","확장 ASCII 코드는 8비트를 사용하여 문자를 표현한다."],"id":"2020-1-A","e":"2020 1회 A형"},{"n":12,"s":1,"a":4,"p":"다음 중 하나의 컴퓨터에 여러 개의 중앙처리장치를 설치하여 주기억장치나 주변장치들을 공유하여 신뢰성과 연산능력을 향상시키는 시스템은?","c":["시분할 처리 시스템(Time Sharing System)","다중 프로그래밍 시스템(Multi-Programming System)","듀플렉스 시스템(Duplex System)","다중 처리 시스템(Multi-Processing System)"],"id":"2020-1-A","e":"2020 1회 A형"},{"n":13,"s":1,"a":1,"p":"다음 중 CPU의 제어장치를 구성하는 레지스터에 관한 설명으로 옳지 않은 것은?","c":["프로그램 카운터: 프로그램의 실행된 명령어의 개수를 계산한다.","명령 레지스터: 현재 실행 중인 명령을 기억한다.","부호기: 해독된 명령에 따라 각 장치로 보낼 제어 신호를 생성한다.","메모리 주소 레지스터: 기억장치에 입출력되는 데이터의 번지를 기억한다. 컴퓨터활용능력 1급 A형 3/7"],"id":"2020-1-A","e":"2020 1회 A형"},{"n":14,"s":1,"a":4,"p":"다음 중 프린터에서 출력할 파일의 해상도를 조절하거나 스캐너를 이용해 스캔한 파일의 해상도를 조절하기 위해 쓰는 단위는?","c":["CPS(Character Per Second)","BPS(Bits Per Second)","PPM(Paper Per Minute)","DPI(Dots Per Inch)"],"id":"2020-1-A","e":"2020 1회 A형"},{"n":15,"s":1,"a":4,"p":"다음 중 BIOS(Basic Input Output System)에 관한 설명으로 옳지 않은 것은?","c":["BIOS는 메인보드 상에 위치한 EPROM, 혹은 플래시 메모리 칩에 저장되어 있다.","컴퓨터의 전원을 켜면 자동으로 가장 먼저 기동되며, 기본 입출력 장치나 메모리 등 하드웨어의 이상 유무를 검사한다.","CMOS 셋업 프로그램을 이용하여 시스템의 날짜와 시간, 부팅 순서 등 일부 BIOS 정보를 설정할 수 있다.","주기억 장치의 접근 속도 개선을 위한 가상 메모리의 페이징 파일 크기를 설정할 수 있다."],"id":"2020-1-A","e":"2020 1회 A형"},{"n":16,"s":1,"a":3,"p":"다음 중 반도체를 이용한 컴퓨터 보조 기억 장치로 크기가 작고 충격에 강하며, 소음 발생이 없는 대용량 저장 장치는?","c":["HDD(Hard Disk Drive)","DVD(Digital Versatile Disk)","SSD(Solid State Drive)","CD-RW(Compact Disc Rewritable)"],"id":"2020-1-A","e":"2020 1회 A형"},{"n":17,"s":1,"a":2,"p":"다음 중 Windows의 [시스템 구성]에 대한 설명으로 옳지 않은 것은?","c":["Windows가 제대로 시작되지 않는 문제를 식별하도록 도와주는 고급 도구이다.","시작 모드 선택에서 ‘선택 모드’는 기본 장치 및 서비스 로만 Windows를 시작하여 발생된 문제를 진단하는데 유용하다.","한 번에 하나씩 공용 서비스 및 시작 프로그램을 끈 상태에서 Windows를 재시작한 후 다시 켤 때 문제가 발생하면 해당 서비스가 문제의 원인임을 알 수 있다.","부팅 옵션 중 ‘안전 부팅’의 ‘최소 설치’를 선택하면 중요한 시스템 서비스만 실행되는 안전 모드로 Windows를 시작하며, 네트워킹은 사용할 수 없다."],"id":"2020-1-A","e":"2020 1회 A형"},{"n":18,"s":1,"a":1,"p":"다음 중 Windows의 [폴더 옵션] 창에서 설정할 수 있는 작업으로 옳지 않은 것은?","c":["탐색 창, 미리 보기 창, 세부 정보 창의 표시 여부를 선택할 수 있다.","숨김 파일이나 폴더의 표시 여부를 지정할 수 있다.","폴더에서 시스템 파일을 검색할 때 색인의 사용 여부를 선택할 수 있다.","알려진 파일 형식의 파일 확장명을 숨기도록 설정할 수 있다."],"id":"2020-1-A","e":"2020 1회 A형"},{"n":19,"s":1,"a":4,"p":"다음 중 Windows의 백업과 복원에 관한 설명으로 옳지 않은 것은?","c":["특정한 날짜나 시간에 주기적으로 백업이 되도록 예약 할 수 있다.","백업에서 사용되는 파일의 확장자는 .bkf 이다.","백업된 파일을 복원할 때 복원 위치를 설정할 수 있다.","직접 선택한 폴더에 있는 알려진 시스템 폴더나 파일도 백업할 수 있다."],"id":"2020-1-A","e":"2020 1회 A형"},{"n":20,"s":1,"a":4,"p":"다음 중 Windows의 작업 표시줄에 대한 설명으로 옳지 않은 것은?","c":["작업 표시줄의 위치나 크기를 변경할 수 있으며, 크기는 화면의 1/2까지만 늘릴 수 있다.","작업 표시줄에 있는 단추를 작은 아이콘으로 표시되도록 설정할 수 있다.","작업 표시줄을 자동으로 숨길 것인지의 여부를 선택할 수 있다.","작업 표시줄에 있는 시작 단추, 검색 상자(검색 아이콘), 작업 보기 단추의 표시 여부를 설정할 수 있다."],"id":"2020-1-A","e":"2020 1회 A형"},{"n":21,"s":2,"a":4,"p":"다음 중 자동 필터와 고급 필터에 대한 설명으로 옳은 것은?","c":["자동 필터는 각 열에 입력된 데이터의 종류가 혼합되어 있는 경우 날짜, 숫자, 텍스트 필터가 모두 표시된다.","고급 필터는 조건을 수식으로 작성할 수 있으며, 조건의 첫 셀은 반드시 필드명으로 입력해야 한다.","자동 필터에서 여러 필드에 조건을 설정한 경우 필드 간은 OR 조건으로 처리되어 결과가 표시된다.","고급 필터는 필터링 한 결과를 원하는 위치에 별도의 표로 생성할 수 있다."],"id":"2020-1-A","e":"2020 1회 A형"},{"n":22,"s":2,"a":4,"p":"다음 중 데이터 정렬에 관한 설명으로 옳지 않은 것은?","c":["대/소문자를 구분하여 정렬할 수 있다.","표 안에서 다른 열에는 영향을 주지 않고 선택한 한 열 내에서만 정렬하도록 할 수 있다.","정렬 기준으로 ‘셀 아이콘’을 선택한 경우 기본 정렬 순서는 ‘위에 표시’이다.","행을 기준으로 정렬하려면 [정렬] 대화상자의 [옵션]에서 정렬 옵션의 방향을 ‘위쪽에서 아래쪽’으로 선택한다."],"id":"2020-1-A","e":"2020 1회 A형"},{"n":23,"s":2,"a":1,"p":"다음 중 시나리오에 대한 설명으로 옳지 않은 것은?","c":["시나리오 요약 보고서를 만들 때에는 결과 셀을 반드시 지정해야 하지만, 시나리오 피벗 테이블 보고서를 만들 때에는 결과 셀을 지정하지 않아도 된다.","여러 시나리오를 비교하여 하나의 테이블로 요약하는 보고서를 만들 수 있다.","시나리오 요약 보고서를 생성하기 전에 변경 셀과 결과 셀에 이름을 정의하면 셀 참조 주소 대신 정의된 이름이 보고서에 표시된다.","시나리오 요약 보고서는 자동으로 다시 갱신되지 않으 므로 변경된 값을 요약 보고서에 표시하려면 새 요약 보고서를 만들어야 한다."],"id":"2020-1-A","e":"2020 1회 A형"},{"n":24,"s":2,"a":3,"p":"다음 중 셀 스타일에 대한 설명으로 옳지 않은 것은?","c":["셀 스타일은 글꼴과 글꼴 크기, 숫자 서식, 셀 테두리, 셀 음영 등의 정의된 서식의 집합으로 셀 서식을 일관성 있게 적용하는 경우 편리하다.","기본 제공 셀 스타일을 수정하거나 복제하여 사용자 지정 셀 스타일을 직접 만들 수 있다.","사용 중인 셀 스타일을 수정한 경우 해당 셀에는 셀 스타일을 다시 적용해야 수정한 서식이 반영된다.","특정 셀을 다른 사람이 변경할 수 없도록 셀을 잠그는 셀 스타일을 사용할 수도 있다. 컴퓨터활용능력 1급 A형 4/7"],"id":"2020-1-A","e":"2020 1회 A형"},{"n":25,"s":2,"a":3,"p":"다음 중 피벗 테이블과 피벗 차트에 대한 설명으로 옳지 않은 것은?","c":["새 워크시트에 피벗 테이블을 생성하면 보고서 필터의 위치는 [A1] 셀, 행 레이블은 [A3] 셀에서 시작한다.","피벗 테이블과 연결된 피벗 차트가 있는 경우 피벗 테이블에서 [피벗테이블 도구]의 [모두 지우기] 명령을 사용하면 피벗 테이블과 피벗 차트의 필드, 서식 및 필터가 제거된다.","하위 데이터 집합에도 필터와 정렬을 적용하여 원하는 정보만 강조할 수 있으나 조건부 서식은 적용되지 않는다.","[피벗 테이블 옵션] 대화 상자에서 오류 값을 빈 셀로 표시하거나 빈 셀에 원하는 값을 지정하여 표시할 수도 있다."],"id":"2020-1-A","e":"2020 1회 A형"},{"n":26,"s":2,"a":3,"p":"다음 중 입력 데이터에 사용자 지정 표시 형식을 설정한 경우 그 표시 결과로 옳지 않은 것은? 입력 데이터 표시 형식 표시 결과","c":["0 #","123.456 #.# 123.5","100 ##.## 100.00","12345 #,### 12,345"],"id":"2020-1-A","e":"2020 1회 A형"},{"n":27,"s":2,"a":2,"p":"다음 중 데이터가 입력된 셀에서 채우기 핸들을 드래그 하여 데이터를 채우는 경우에 대한 설명으로 옳은 것은?","c":["일반적인 문자 데이터나 날짜 데이터는 그대로 복사되어 채워진다.","1개의 숫자와 문자가 조합된 텍스트 데이터는 숫자만 1씩 증가하고 문자는 그대로 복사되어 채워진다.","숫자 데이터는 1씩 증가하면서 채워진다.","숫자가 입력된 두 셀을 블록 설정하여 채우기 핸들을 드래그하면 두 숫자가 반복하여 채워진다."],"id":"2020-1-A","e":"2020 1회 A형"},{"n":28,"s":2,"a":1,"p":"다음 중 셀 포인터의 이동 작업에 대한 설명으로 옳지 않은 것은?","c":["<Alt> + <Page Down> 키를 눌러 현재 시트를 기준 으로 오른쪽에 있는 다음 시트로 이동한다.","이름 상자에 셀 주소를 입력한 후 <Enter> 키를 눌러 원하는 셀의 위치로 이동한다.","<Ctrl> + <Home> 키를 눌러 [A1] 셀로 이동한다.","<Home> 키를 눌러 해당 행의 A 열로 이동한다."],"id":"2020-1-A","e":"2020 1회 A형"},{"n":29,"s":2,"a":4,"p":"다음 중 아래 시트의 [A9] 셀에 수식 ‘=OFFSET(B3,-1,2)’을 입력한 경우 결과값은?","c":["윤혜주","서울","고양","박태훈"],"id":"2020-1-A","e":"2020 1회 A형"},{"n":30,"s":2,"a":3,"p":"다음 중 [개발 도구] 탭의 [컨트롤] 그룹에 대한 설명으로 옳지 않는 것은?","c":["컨트롤 종류에는 텍스트 상자, 목록 상자, 옵션 단추, 명령 단추 등이 있다.","ActiveX 컨트롤은 양식 컨트롤 보다 다양한 이벤트에 반응할 수 있지만, 양식 컨트롤보다 호환성은 낮다.","[디자인 모드] 상태에서는 양식 컨트롤과 ActiveX 컨트롤 모두 매크로 등 정해진 동작은 실행하지 않지만 컨트롤의 선택, 크기 조절, 이동 등의 작업을 할 수 있다.","양식 컨트롤의 ‘단추(양식 컨트롤)’를 클릭하거나 드래그 해서 추가하면 [매크로 지정] 대화상자가 자동으로 표시 된다."],"id":"2020-1-A","e":"2020 1회 A형"},{"n":31,"s":2,"a":2,"p":"다음 중 아래의 프로시저가 실행된 후 [A1] 셀에 입력 되는 값으로 옳은 것은? Sub 예제( ) Test = 0 Do Until Test > 10 Test = Test + 1 Loop Range(\"A1\").Value = Test End Sub","c":["10","11","0","55"],"id":"2020-1-A","e":"2020 1회 A형"},{"n":32,"s":2,"a":4,"p":"다음 중 아래 시트에 대한 각 수식의 결과값이 나머지 셋과 다른 것은?","c":["=SMALL(A1:G1,{3})","=AVERAGE(SMALL(A1:G1,{1;2;3;4;5}))","=LARGE(A1:G1,{5})","=SMALL(A1:G1,COLUMN(D1))"],"id":"2020-1-A","e":"2020 1회 A형"},{"n":33,"s":2,"a":4,"p":"아래 시트에서 주민등록번호의 여덟 번째 문자가 ‘1’ 또는 ‘3’이면 ‘남’, ‘2’ 또는 ‘4’이면 ‘여’로 성별 정보를 알 수 있다. 다음 중 성별을 계산하기 위한 [D2] 셀의 수식으로 옳지 않은 것은? (단, [F2:F5] 영역은 숫자 데이터임)","c":["=IF(OR(MID(C2, 8, 1)=\"2\", MID(C2, 8, 1)=\"4\"), \"여\", \"남\")","=CHOOSE(VALUE(MID(C2, 8, 1)), \"남\", \"여\", \"남\", \"여\")","=VLOOKUP(VALUE(MID(C2, 8, 1)), $F$2:$G$5, 2, 0)","=IF(MOD(VALUE(MID(C2, 8, 1)), 2)=0, \"남\", \"여\") 컴퓨터활용능력 1급 A형 5/7"],"id":"2020-1-A","e":"2020 1회 A형"},{"n":34,"s":2,"a":3,"p":"아래 시트에서 국적별 영화 장르의 편수를 계산하기 위해 [B12] 셀에 작성해야 할 배열수식으로 옳지 않은 것은?","c":["{=SUM(($D$2:$D$9=$A12) * ($E$2:$E$9=B$11))}","{=SUM(IF($D$2:$D$9=$A12, IF($E$2:$E$9=B$11, 1)))}","{=COUNT(($D$2:$D$9=$A12) * ($E$2:$E$9=B$11))}","{=COUNT(IF(($D$2:$D$9=$A12) * ($E$2:$E$9=B$11), 1))}"],"id":"2020-1-A","e":"2020 1회 A형"},{"n":35,"s":2,"a":3,"p":"다음 중 이름 상자에 대한 설명으로 옳지 않은 것은?","c":["<Ctrl> 키를 누르고 여러 개의 셀을 선택한 경우 마지막 선택한 셀 주소가 표시된다.","셀이나 셀 범위에 이름을 정의해 놓은 경우 이름이 표시 된다.","차트가 선택되어 있는 경우 차트의 종류가 표시된다.","수식을 작성 중인 경우 최근 사용한 함수 목록이 표시 된다."],"id":"2020-1-A","e":"2020 1회 A형"},{"n":36,"s":2,"a":2,"p":"다음 중 엑셀의 화면 확대/축소 작업에 관한 설명으로 옳지 않은 것은?","c":["문서의 확대/축소는 10%에서 400%까지 설정할 수 있다.","설정한 확대/축소 배율은 통합 문서의 모든 시트에 자동으로 적용된다.","화면의 확대/축소는 단지 화면에서 보이는 상태만을 확대/축소하는 것으로 인쇄 시 적용되지 않는다.","<Ctrl> 키를 누른 채 마우스의 스크롤을 위로 올리면 화면이 확대되고, 아래로 내리면 화면이 축소된다."],"id":"2020-1-A","e":"2020 1회 A형"},{"n":37,"s":2,"a":2,"p":"다음 중 인쇄 기능에 대한 설명으로 옳지 않은 것은?","c":["기본적으로 워크시트의 눈금선은 인쇄되지 않으나 인쇄 되도록 설정할 수 있다.","[페이지 설정] 대화상자의 [시트] 탭에서 ‘간단하게 인쇄’ 를 선택하면 셀의 테두리를 포함하여 인쇄할 수 있다.","[인쇄 미리 보기 및 인쇄] 화면을 표시하는 단축키는 <Ctrl> + <F2> 이다.","[인쇄 미리 보기 및 인쇄]에서 ‘여백 표시’를 선택한 경우 마우스로 여백을 변경할 수 있다."],"id":"2020-1-A","e":"2020 1회 A형"},{"n":38,"s":2,"a":3,"p":"다음 중 차트 도구의 [데이터 선택]에 대한 설명으로 옳지 않은 것은?","c":["[차트 데이터 범위]에서 차트에 사용하는 데이터 전체의 범위를 수정할 수 있다.","[행/열 전환]을 클릭하여 가로 (항목) 축의 데이터 계열과 범례 항목(계열)을 바꿀 수 있다.","범례에서 표시되는 데이터 계열의 순서를 바꿀 수 없다.","데이터 범위 내에 숨겨진 행이나 열의 데이터도 차트에 표시할 수 있다."],"id":"2020-1-A","e":"2020 1회 A형"},{"n":39,"s":2,"a":3,"p":"다음 중 아래 데이터를 차트로 작성하여 사원별로 각 분기의 실적을 비교·분석하려는 경우 가장 비효율적인 차트는?","c":["누적 세로 막대형 차트","표식이 있는 꺾은선형","원형 대 가로 막대형","묶은 가로 막대형"],"id":"2020-1-A","e":"2020 1회 A형"},{"n":40,"s":2,"a":2,"p":"다음 중 셀 영역을 선택한 후 상태 표시줄의 바로 가기 메뉴인 [상태 표시줄 사용자 지정]에서 선택할 수 있는 자동 계산에 해당되지 않는 것은?","c":["선택한 영역 중 숫자 데이터가 입력된 셀의 수","선택한 영역 중 문자 데이터가 입력된 셀의 수","선택한 영역 중 데이터가 입력된 셀의 수","선택한 영역의 합계, 평균, 최소값, 최대값"],"id":"2020-1-A","e":"2020 1회 A형"},{"n":41,"s":3,"a":2,"p":"다음 중 Access 파일에 암호를 설정하는 방법으로 옳은 것은?","c":["[데이터베이스 압축 및 복구] 도구에서 파일 암호를 설정할 수 있다.","데이터베이스를 단독 사용 모드(단독으로 열기)로 열어야 파일 암호를 설정할 수 있다.","데이터베이스를 MDE 형식으로 저장한 후 파일을 열어야 파일 암호를 설정할 수 있다.","[Access 옵션] 창의 보안 센터에서 파일 암호를 설정 할 수 있다."],"id":"2020-1-A","e":"2020 1회 A형"},{"n":42,"s":3,"a":1,"p":"다음 중 데이터 보안 및 회복, 무결성, 병행 수행 제어 등 을 정의하는 데이터베이스 언어로 데이터베이스 관리자가 데이터 관리를 목적으로 주로 사용하는 언어는?","c":["데이터 제어어(DCL)","데이터 부속어(DSL)","데이터 정의어(DDL)","데이터 조작어(DML)"],"id":"2020-1-A","e":"2020 1회 A형"},{"n":43,"s":3,"a":1,"p":"다음 중 SQL 질의에 대한 설명으로 옳지 않은 것은?","c":["ORDER BY절 사용 시 정렬방식을 별도로 지정하지 않으면 기본 값은 ‘DESC’로 적용된다.","GROUP BY절은 특정 필드를 기준으로 그룹화 하여 검색할 때 사용한다.","FROM절에는 테이블 또는 쿼리 이름을 지정하며, WHERE절에는 조건을 지정한다.","SELECT DISTINCT문을 사용하면 중복 레코드를 제거 할 수 있다. 컴퓨터활용능력 1급 A형 6/7"],"id":"2020-1-A","e":"2020 1회 A형"},{"n":44,"s":3,"a":4,"p":"다음 중 보고서의 그룹화 및 정렬에 대한 설명으로 옳지 않은 것은?","c":["‘그룹’은 머리글과 같은 소계 및 요약 정보와 함께 표시 되는 레코드의 모음으로 그룹 머리글, 세부 레코드 및 그룹 바닥글로 구성된다.","그룹화 할 필드가 날짜 데이터이면 전체 값(기본), 일, 주, 월, 분기, 연도 중 선택한 기준으로 그룹화 할 수 있다.","Sum 함수를 사용하는 계산 컨트롤을 그룹 머리글에 추가하면 현재 그룹에 대한 합계를 표시할 수 있다.","필드나 식을 기준으로 최대 5단계까지 그룹화 할 수 있으며, 같은 필드나 식은 한 번씩만 그룹화 할 수 있다."],"id":"2020-1-A","e":"2020 1회 A형"},{"n":45,"s":3,"a":2,"p":"다음 중 보고서 작업 시 필드 목록 창에서 선택한 필드를 본문 영역에 추가할 때 자동으로 생성되는 컨트롤은?","c":["단추","텍스트 상자","하이퍼링크","언바운드 개체 틀"],"id":"2020-1-A","e":"2020 1회 A형"},{"n":46,"s":3,"a":1,"p":"다음 중 보고서의 보기 형태에 대한 설명으로 옳지 않은 것은?","c":["[보고서 보기]는 출력되는 보고서를 화면 출력용으로 보여주며 페이지를 구분하여 표시한다.","[디자인 보기]에서는 보고서에 삽입된 컨트롤의 속성, 맞춤, 위치 등을 설정할 수 있다.","[레이아웃 보기]는 출력될 보고서의 레이아웃을 보여주며 컨트롤의 크기 및 위치를 변경할 수도 있다.","[인쇄 미리 보기]에서는 종이에 출력되는 모양을 표시 하며 인쇄를 위한 페이지 설정이 용이하다."],"id":"2020-1-A","e":"2020 1회 A형"},{"n":47,"s":3,"a":1,"p":"다음 중 아래 보고서에 대한 설명으로 옳지 않은 것은?","c":["‘모델명’ 필드를 기준으로 그룹이 설정되어 있다.","‘모델명’ 필드에는 ‘중복 내용 숨기기’ 속성을 ‘예’로 설정하였다.","지점별 소계가 표시된 텍스트 상자는 그룹 바닥글에 삽입하였다.","순번은 컨트롤 원본을 ‘=1’ 로 입력한 후 ‘누적 합계’ 속성을 ‘그룹’으로 설정하였다."],"id":"2020-1-A","e":"2020 1회 A형"},{"n":48,"s":3,"a":4,"p":"다음 중 아래 <학생> 테이블에 대한 SQL문의 실행 결과로 옳은 것은? SELECT AVG([나이]) FROM 학생 WHERE 학년=\"SN\" GROUP BY 전공 HAVING COUNT(*) >= 2;","c":["21","22","23","24"],"id":"2020-1-A","e":"2020 1회 A형"},{"n":49,"s":3,"a":3,"p":"다음 중 선택 쿼리에서 사용자가 지정한 패턴과 일치하는 데이터를 찾고자 할 때 사용되는 연산자는?","c":["Match","Some","Like","Any"],"id":"2020-1-A","e":"2020 1회 A형"},{"n":50,"s":3,"a":4,"p":"다음 중 아래 SQL문으로 생성된 테이블에서의 레코드 작업에 대한 설명으로 옳지 않은 것은? (단, 고객과 계좌 간의 관계는 1:M이다.) CREATE TABLE 고객 (고객ID CHAR(20) NOT NULL, 고객명 CHAR(20) NOT NULL, 연락번호 CHAR(12), PRIMARY KEY (고객ID) ); CREATE TABLE 계좌 (계좌번호 CHAR(10) NOT NULL, 고객ID CHAR(20) NOT NULL, 잔액 INTEGER DEFAULT 0, PRIMARY KEY (계좌번호), FOREIGN KEY (고객ID) REFERENCES 고객 );","c":["<고객> 테이블에서 ‘고객ID’ 필드는 동일한 값을 입력 할 수 없다.","<계좌> 테이블에서 ‘계좌번호’ 필드는 반드시 입력해야 한다.","<고객> 테이블에서 ‘연락번호’ 필드는 원하는 값으로 수정하거나 생략할 수 있다.","<계좌> 테이블에서 ‘고객ID’ 필드는 동일한 값을 입력 할 수 없다."],"id":"2020-1-A","e":"2020 1회 A형"},{"n":51,"s":3,"a":1,"p":"다음 중 테이블에서 입력 마스크를 “LA09?”로 설정한 경우 입력할 수 없는 값은?","c":["AA111","A11","AA11","A111A 컴퓨터활용능력 1급 A형 7/7"],"id":"2020-1-A","e":"2020 1회 A형"},{"n":52,"s":3,"a":3,"p":"다음 중 아래 <고객>과 <구매리스트> 테이블 관계에 참조 무결성이 항상 유지되도록 설정할 수 없는 경우는?","c":["<고객> 테이블의 ‘고객번호’ 필드 값이 <구매리스트> 테이블의 ‘고객번호’ 필드에 없는 경우","<고객> 테이블의 ‘고객번호’ 필드 값이 <구매리스트> 테이블의 ‘고객번호’ 필드에 하나만 있는 경우","<구매리스트> 테이블의 ‘고객번호’ 필드 값이 <고객> 테이블의 ‘고객번호’ 필드에 없는 경우","<고객> 테이블의 ‘고객번호’ 필드 값이 <구매리스트> 테이블의 ‘고객번호’ 필드에 두 개 이상 있는 경우"],"id":"2020-1-A","e":"2020 1회 A형"},{"n":53,"s":3,"a":1,"p":"다음 중 외부 데이터 가져오기 기능에 대한 설명으로 옳지 않은 것은?","c":["텍스트 파일을 가져와 기존 테이블의 레코드로 추가 하려는 경우 기본 키에 해당하는 필드의 값들이 고유한 값이 되도록 데이터를 수정하며 가져올 수 있다.","Excel 워크시트에서 정의된 이름의 영역을 Access의 새 테이블이나 기존 테이블에 데이터 복사본으로 만들 수 있다.","Access에서는 한 테이블에 256개 이상의 필드를 지원 하지 않으므로 원본 데이터는 열의 개수가 255개를 초과 하지 않아야 한다.","Excel 파일을 가져오는 경우 한 번에 하나의 워크시트만 가져올 수 있으므로 여러 워크시트에서 데이터를 가져 오려면 각 워크시트에 대해 가져오기 명령을 반복해야 한다."],"id":"2020-1-A","e":"2020 1회 A형"},{"n":54,"s":3,"a":2,"p":"다음 중 위쪽 구역에 데이터시트를 표시하는 열 형식의 폼을 만들고, 아래쪽 구역에 선택한 레코드에 대한 정보를 수정하거나 입력할 수 있는 데이터시트 형식의 폼을 자동으로 만들어 주는 도구는?","c":["폼","폼 분할","여러 항목","폼 디자인"],"id":"2020-1-A","e":"2020 1회 A형"},{"n":55,"s":3,"a":1,"p":"다음 중 이벤트 프로시저에서 쿼리를 실행 모드로 여는 명령은?","c":["DoCmd.OpenQuery","DoCmd.SetQuery","DoCmd.QueryView","DoCmd.QueryTable"],"id":"2020-1-A","e":"2020 1회 A형"},{"n":56,"s":3,"a":1,"p":"다음 중 폼의 구성요소에 대한 설명으로 옳지 않은 것은?","c":["폼 머리글은 인쇄할 때 모든 페이지의 상단에 매번 표시된다.","하위 폼은 폼 안에 있는 또 하나의 폼을 의미한다.","폼 바닥글은 폼 요약 정보 등과 같이 각 레코드에 동일 하게 표시될 정보가 입력되는 구역이다.","본문은 사용할 실제 내용을 입력하는 구역으로 폼 보기 형식에 따라 하나의 레코드만 표시하거나 여러 개의 레코드를 표시한다."],"id":"2020-1-A","e":"2020 1회 A형"},{"n":57,"s":3,"a":2,"p":"다음 중 폼 작성에 관한 설명으로 옳지 않은 것은?","c":["여러 개의 컨트롤을 선택하여 자동 정렬할 수 있다.","컨트롤의 탭 순서는 자동으로 화면 위에서 아래로 설정 된다.","사각형, 선 등의 도형 컨트롤을 삽입할 수 있다.","컨트롤 마법사를 사용하여 폼을 닫는 매크로를 실행 시키는 단추를 만들 수 있다."],"id":"2020-1-A","e":"2020 1회 A형"},{"n":58,"s":3,"a":4,"p":"다음 중 관계형 데이터베이스의 조인(JOIN)에 대한 설명으로 옳지 않은 것은?","c":["쿼리에 여러 테이블을 포함할 때는 조인을 사용하여 원하는 결과를 얻을 수 있다.","내부 조인은 조인되는 두 테이블에서 조인하는 필드가 일치하는 행만을 반환하려는 경우에 사용한다.","외부 조인은 조인되는 두 테이블에서 공통 값이 없는 데이터를 포함할지 여부를 지정할 수 있다.","조인에 사용되는 기준 필드의 데이터 형식은 다르거나 호환되지 않아도 가능하다."],"id":"2020-1-A","e":"2020 1회 A형"},{"n":59,"s":3,"a":1,"p":"다음 중 폼 바닥글의 텍스트 상자의 컨트롤 원본으로 <사원> 테이블에서 직급이 ‘부장’인 레코드들의 급여 평균을 구하는 함수식으로 옳은 것은?","c":["=DAVG(“[급여]”, “[사원]”, “[직급]=‘부장’”)","=DAVG(“[사원]”, “[급여]”, “[직급]=‘부장’”)","=AVG(“[급여]”, “[사원]”, “[직급]=‘부장’”)","=AVG(“[사원]”, “[급여]”, “[직급]=‘부장’”)"],"id":"2020-1-A","e":"2020 1회 A형"},{"n":60,"s":3,"a":4,"p":"다음 중 액세스의 매크로에 대한 설명으로 옳지 않은 것은?","c":["반복적으로 수행되는 작업을 자동화하여 간단히 처리할 수 있도록 하는 기능이다.","매크로 함수 또는 매크로 함수 집합으로 구성되며, 각 매크로 함수의 수행 방식을 제어하는 인수를 추가할 수 있다.","매크로를 이용하여 폼을 열고 닫거나 메시지 박스를 표시할 수도 있다.","매크로는 주로 컨트롤의 이벤트에 연결하여 사용하며, 폼 개체 내에서만 사용할 수 있다. * 수고하셨습니다. 수험자 여러분의 좋은 결과를 기원합니다."],"id":"2020-1-A","e":"2020 1회 A형"}]},{"id":"2020-1-B","t":"2020 1회 B형","q":[{"n":1,"s":1,"a":2,"p":"다음 중 VoIP에 대한 설명으로 옳지 않은 것은?","c":["인터넷 IP 기술을 사용한 디지털 음성 전송 기술이다.","원거리 통화 시 PSTN(public switched telephone network) 보다는 요금이 높지만 일정 수준의 통화 품질이 보장된다.","기존 회선교환 방식과 달리 네트워크를 통해 음성을 패킷형태로 전송한다.","보컬텍(VocalTec)사의 인터넷폰으로 처음 소개되었으며, PC to PC, PC to Phone, Phone to Phone 방식으로 발전하였다."],"id":"2020-1-B","e":"2020 1회 B형"},{"n":2,"s":1,"a":2,"p":"다음 중 대량의 데이터 안에서 일정한 패턴을 찾아내고, 이로부터 가치 있는 정보를 추출해내는 기술을 의미하는 것은?","c":["데이터 웨어하우스(Data Warehouse)","데이터 마이닝(Data Mining)","데이터 마이그레이션(Data Migration)","메타데이터(Metadata)"],"id":"2020-1-B","e":"2020 1회 B형"},{"n":3,"s":1,"a":3,"p":"다음 중 사운드의 압축 및 복원과 관련된 기술에 해당하지 않는 것은?","c":["FLAC","AIFF","H.264","WAV"],"id":"2020-1-B","e":"2020 1회 B형"},{"n":4,"s":1,"a":2,"p":"다음 중 컴퓨터 게임이나 컴퓨터 기반 훈련과 같이 사용자 와의 상호작용을 통해 진행 상황을 제어하는 멀티미디어의 특징을 나타내는 용어는?","c":["선형 콘텐츠","비선형 콘텐츠","VR 콘텐츠","4D 콘텐츠"],"id":"2020-1-B","e":"2020 1회 B형"},{"n":5,"s":1,"a":3,"p":"다음 중 정보 보안을 위한 비밀키 암호화 기법에 대한 설명으로 옳지 않은 것은?","c":["비밀키 암호화 기법의 안전성은 키의 길이 및 키의 비밀성 유지 여부에 영향을 많이 받는다.","암호화와 복호화 시 사용하는 키가 동일한 암호화 기법 이다.","복잡한 알고리즘으로 인해 암호화와 복호화 속도가 느리다.","사용자가 증가할 경우 상대적으로 관리해야 할 키의 수가 많아진다."],"id":"2020-1-B","e":"2020 1회 B형"},{"n":6,"s":1,"a":3,"p":"다음 중 분산 서비스 거부 공격(DDos)에 관한 설명으로 옳은 것은?","c":["네트워크 주변을 돌아다니는 패킷을 엿보면서 계정과 패스워드를 알아내는 행위","검증된 사람이 네트워크를 통해 데이터를 보낸 것처럼 데이터를 변조하여 접속을 시도하는 행위","여러 대의 장비를 이용하여 특정 서버에 대량의 데이터를 집중적으로 전송함으로써 서버의 정상적인 동작을 방해 하는 행위","키보드의 키 입력시 캐치 프로그램을 사용하여 ID나 암호 정보를 빼내는 행위"],"id":"2020-1-B","e":"2020 1회 B형"},{"n":7,"s":1,"a":3,"p":"다음 중 ASCII 코드에 대한 설명으로 옳지 않은 것은?","c":["3개의 Zone 비트와 4개의 Digit 비트로 하나의 문자를 표현한다.","데이터 통신용으로 사용하며, 128가지 문자를 표현할 수 있다.","2비트의 에러 검출 및 1비트의 에러 교정 비트를 포함 한다.","확장 ASCII 코드는 8비트를 사용하여 문자를 표현한다."],"id":"2020-1-B","e":"2020 1회 B형"},{"n":8,"s":1,"a":4,"p":"다음 중 하나의 컴퓨터에 여러 개의 중앙처리장치를 설치하여 주기억장치나 주변장치들을 공유하여 신뢰성과 연산능력을 향상시키는 시스템은?","c":["시분할 처리 시스템(Time Sharing System)","다중 프로그래밍 시스템(Multi-Programming System)","듀플렉스 시스템(Duplex System)","다중 처리 시스템(Multi-Processing System)"],"id":"2020-1-B","e":"2020 1회 B형"},{"n":9,"s":1,"a":1,"p":"다음 중 CPU의 제어장치를 구성하는 레지스터에 관한 설명으로 옳지 않은 것은?","c":["프로그램 카운터: 프로그램의 실행된 명령어의 개수를 계산한다.","명령 레지스터: 현재 실행 중인 명령을 기억한다.","부호기: 해독된 명령에 따라 각 장치로 보낼 제어 신호를 생성한다.","메모리 주소 레지스터: 기억장치에 입출력되는 데이터의 번지를 기억한다."],"id":"2020-1-B","e":"2020 1회 B형"},{"n":10,"s":1,"a":4,"p":"다음 중 네트워크 프로토콜(Protocol)의 기능에 해당하지 않는 것은?","c":["패킷 수를 조정하는 흐름 제어 기능","송/수신기를 같은 상태로 유지하는 동기화 기능","데이터 전송 도중에 발생하는 에러 검출 기능","네트워크 기반 하드웨어 연결문제 해결 기능"],"id":"2020-1-B","e":"2020 1회 B형"},{"n":11,"s":1,"a":4,"p":"다음 중 인터넷 서버까지의 경로를 추적하는 명령어인 ‘Tracert’의 실행 결과에 관한 설명으로 옳지 않은 것은?","c":["IP 주소, 목적지까지 거치는 경로의 수, 각 구간 사이의 데이터 왕복 속도를 확인할 수 있다.","특정 사이트가 열리지 않을 때 해당 서버가 문제인지 인터넷 망이 문제인지 확인할 수 있다.","인터넷 속도가 느릴 때 어느 구간에서 정체를 일으키는지 확인할 수 있다.","현재 자신의 컴퓨터에 연결된 다른 컴퓨터의 IP 주소나 포트 정보를 확인할 수 있다."],"id":"2020-1-B","e":"2020 1회 B형"},{"n":12,"s":1,"a":2,"p":"다음 중 IPv6 주소에 관한 설명으로 옳지 않은 것은?","c":["16비트씩 8부분으로 총 128비트로 구성된다.","각 부분은 10진수로 표현되며, 세미콜론(;)으로 구분한다.","주소체계는 유니캐스트, 멀티캐스트, 애니캐스트로 나누어진다.","실시간 흐름 제어로 향상된 멀티미디어 기능을 지원한다."],"id":"2020-1-B","e":"2020 1회 B형"},{"n":13,"s":1,"a":3,"p":"다음 중 객체지향 프로그래밍 특징으로 옳은 것은?","c":["객체에 대하여 절차적 프로그래밍의 장점을 사용할 수 있다.","객체지향 프로그램은 주로 인터프리터 번역 방식을 사용한다.","객체지향 프로그램은 코드의 재사용과 유지보수가 용이 하다.","프로그램의 구조와 절차에 중점을 두고 작업을 진행한다. 컴퓨터활용능력 1급 B형 3/7"],"id":"2020-1-B","e":"2020 1회 B형"},{"n":14,"s":1,"a":2,"p":"다음 중 Windows의 [시스템 구성]에 대한 설명으로 옳지 않은 것은?","c":["Windows가 제대로 시작되지 않는 문제를 식별하도록 도와주는 고급 도구이다.","시작 모드 선택에서 ‘선택 모드’는 기본 장치 및 서비스 로만 Windows를 시작하여 발생된 문제를 진단하는데 유용하다.","한 번에 하나씩 공용 서비스 및 시작 프로그램을 끈 상태에서 Windows를 재시작한 후 다시 켤 때 문제가 발생하면 해당 서비스가 문제의 원인임을 알 수 있다.","부팅 옵션 중 ‘안전 부팅’의 ‘최소 설치’를 선택하면 중요한 시스템 서비스만 실행되는 안전 모드로 Windows를 시작하며, 네트워킹은 사용할 수 없다."],"id":"2020-1-B","e":"2020 1회 B형"},{"n":15,"s":1,"a":1,"p":"다음 중 Windows의 [폴더 옵션] 창에서 설정할 수 있는 작업으로 옳지 않은 것은?","c":["탐색 창, 미리 보기 창, 세부 정보 창의 표시 여부를 선택할 수 있다.","숨김 파일이나 폴더의 표시 여부를 지정할 수 있다.","폴더에서 시스템 파일을 검색할 때 색인의 사용 여부를 선택할 수 있다.","알려진 파일 형식의 파일 확장명을 숨기도록 설정할 수 있다."],"id":"2020-1-B","e":"2020 1회 B형"},{"n":16,"s":1,"a":4,"p":"다음 중 Windows의 백업과 복원에 관한 설명으로 옳지 않은 것은?","c":["특정한 날짜나 시간에 주기적으로 백업이 되도록 예약 할 수 있다.","백업에서 사용되는 파일의 확장자는 .bkf 이다.","백업된 파일을 복원할 때 복원 위치를 설정할 수 있다.","직접 선택한 폴더에 있는 알려진 시스템 폴더나 파일도 백업할 수 있다."],"id":"2020-1-B","e":"2020 1회 B형"},{"n":17,"s":1,"a":4,"p":"다음 중 프린터에서 출력할 파일의 해상도를 조절하거나 스캐너를 이용해 스캔한 파일의 해상도를 조절하기 위해 쓰는 단위는?","c":["CPS(Character Per Second)","BPS(Bits Per Second)","PPM(Paper Per Minute)","DPI(Dots Per Inch)"],"id":"2020-1-B","e":"2020 1회 B형"},{"n":18,"s":1,"a":4,"p":"다음 중 BIOS(Basic Input Output System)에 관한 설명으로 옳지 않은 것은?","c":["BIOS는 메인보드 상에 위치한 EPROM, 혹은 플래시 메모리 칩에 저장되어 있다.","컴퓨터의 전원을 켜면 자동으로 가장 먼저 기동되며, 기본 입출력 장치나 메모리 등 하드웨어의 이상 유무를 검사한다.","CMOS 셋업 프로그램을 이용하여 시스템의 날짜와 시간, 부팅 순서 등 일부 BIOS 정보를 설정할 수 있다.","주기억 장치의 접근 속도 개선을 위한 가상 메모리의 페이징 파일 크기를 설정할 수 있다."],"id":"2020-1-B","e":"2020 1회 B형"},{"n":19,"s":1,"a":3,"p":"다음 중 반도체를 이용한 컴퓨터 보조 기억 장치로 크기가 작고 충격에 강하며, 소음 발생이 없는 대용량 저장 장치는?","c":["HDD(Hard Disk Drive)","DVD(Digital Versatile Disk)","SSD(Solid State Drive)","CD-RW(Compact Disc Rewritable)"],"id":"2020-1-B","e":"2020 1회 B형"},{"n":20,"s":1,"a":4,"p":"다음 중 Windows의 작업 표시줄에 대한 설명으로 옳지 않은 것은?","c":["작업 표시줄의 위치나 크기를 변경할 수 있으며, 크기는 화면의 1/2까지만 늘릴 수 있다.","작업 표시줄에 있는 단추를 작은 아이콘으로 표시되도록 설정할 수 있다.","작업 표시줄을 자동으로 숨길 것인지의 여부를 선택할 수 있다.","작업 표시줄에 있는 시작 단추, 검색 상자(검색 아이콘), 작업 보기 단추의 표시 여부를 설정할 수 있다."],"id":"2020-1-B","e":"2020 1회 B형"},{"n":21,"s":2,"a":1,"p":"다음 중 시나리오에 대한 설명으로 옳지 않은 것은?","c":["시나리오 요약 보고서를 만들 때에는 결과 셀을 반드시 지정해야 하지만, 시나리오 피벗 테이블 보고서를 만들 때에는 결과 셀을 지정하지 않아도 된다.","여러 시나리오를 비교하여 하나의 테이블로 요약하는 보고서를 만들 수 있다.","시나리오 요약 보고서를 생성하기 전에 변경 셀과 결과 셀에 이름을 정의하면 셀 참조 주소 대신 정의된 이름이 보고서에 표시된다.","시나리오 요약 보고서는 자동으로 다시 갱신되지 않으 므로 변경된 값을 요약 보고서에 표시하려면 새 요약 보고서를 만들어야 한다."],"id":"2020-1-B","e":"2020 1회 B형"},{"n":22,"s":2,"a":3,"p":"다음 중 셀 스타일에 대한 설명으로 옳지 않은 것은?","c":["셀 스타일은 글꼴과 글꼴 크기, 숫자 서식, 셀 테두리, 셀 음영 등의 정의된 서식의 집합으로 셀 서식을 일관성 있게 적용하는 경우 편리하다.","기본 제공 셀 스타일을 수정하거나 복제하여 사용자 지정 셀 스타일을 직접 만들 수 있다.","사용 중인 셀 스타일을 수정한 경우 해당 셀에는 셀 스타일을 다시 적용해야 수정한 서식이 반영된다.","특정 셀을 다른 사람이 변경할 수 없도록 셀을 잠그는 셀 스타일을 사용할 수도 있다."],"id":"2020-1-B","e":"2020 1회 B형"},{"n":23,"s":2,"a":4,"p":"다음 중 자동 필터와 고급 필터에 대한 설명으로 옳은 것은?","c":["자동 필터는 각 열에 입력된 데이터의 종류가 혼합되어 있는 경우 날짜, 숫자, 텍스트 필터가 모두 표시된다.","고급 필터는 조건을 수식으로 작성할 수 있으며, 조건의 첫 셀은 반드시 필드명으로 입력해야 한다.","자동 필터에서 여러 필드에 조건을 설정한 경우 필드 간은 OR 조건으로 처리되어 결과가 표시된다.","고급 필터는 필터링 한 결과를 원하는 위치에 별도의 표로 생성할 수 있다."],"id":"2020-1-B","e":"2020 1회 B형"},{"n":24,"s":2,"a":4,"p":"다음 중 데이터 정렬에 관한 설명으로 옳지 않은 것은?","c":["대/소문자를 구분하여 정렬할 수 있다.","표 안에서 다른 열에는 영향을 주지 않고 선택한 한 열 내에서만 정렬하도록 할 수 있다.","정렬 기준으로 ‘셀 아이콘’을 선택한 경우 기본 정렬 순서는 ‘위에 표시’이다.","행을 기준으로 정렬하려면 [정렬] 대화상자의 [옵션]에서 정렬 옵션의 방향을 ‘위쪽에서 아래쪽’으로 선택한다. 컴퓨터활용능력 1급 B형 4/7"],"id":"2020-1-B","e":"2020 1회 B형"},{"n":25,"s":2,"a":1,"p":"다음 중 셀 포인터의 이동 작업에 대한 설명으로 옳지 않은 것은?","c":["<Alt> + <Page Down> 키를 눌러 현재 시트를 기준 으로 오른쪽에 있는 다음 시트로 이동한다.","이름 상자에 셀 주소를 입력한 후 <Enter> 키를 눌러 원하는 셀의 위치로 이동한다.","<Ctrl> + <Home> 키를 눌러 [A1] 셀로 이동한다.","<Home> 키를 눌러 해당 행의 A 열로 이동한다."],"id":"2020-1-B","e":"2020 1회 B형"},{"n":26,"s":2,"a":4,"p":"다음 중 아래 시트의 [A9] 셀에 수식 ‘=OFFSET(B3,-1,2)’을 입력한 경우 결과값은?","c":["윤혜주","서울","고양","박태훈"],"id":"2020-1-B","e":"2020 1회 B형"},{"n":27,"s":2,"a":3,"p":"다음 중 피벗 테이블과 피벗 차트에 대한 설명으로 옳지 않은 것은?","c":["새 워크시트에 피벗 테이블을 생성하면 보고서 필터의 위치는 [A1] 셀, 행 레이블은 [A3] 셀에서 시작한다.","피벗 테이블과 연결된 피벗 차트가 있는 경우 피벗 테이블에서 [피벗테이블 도구]의 [모두 지우기] 명령을 사용하면 피벗 테이블과 피벗 차트의 필드, 서식 및 필터가 제거된다.","하위 데이터 집합에도 필터와 정렬을 적용하여 원하는 정보만 강조할 수 있으나 조건부 서식은 적용되지 않는다.","[피벗 테이블 옵션] 대화 상자에서 오류 값을 빈 셀로 표시하거나 빈 셀에 원하는 값을 지정하여 표시할 수도 있다."],"id":"2020-1-B","e":"2020 1회 B형"},{"n":28,"s":2,"a":3,"p":"다음 중 입력 데이터에 사용자 지정 표시 형식을 설정한 경우 그 표시 결과로 옳지 않은 것은? 입력 데이터 표시 형식 표시 결과","c":["0 #","123.456 #.# 123.5","100 ##.## 100.00","12345 #,### 12,345"],"id":"2020-1-B","e":"2020 1회 B형"},{"n":29,"s":2,"a":2,"p":"다음 중 데이터가 입력된 셀에서 채우기 핸들을 드래그 하여 데이터를 채우는 경우에 대한 설명으로 옳은 것은?","c":["일반적인 문자 데이터나 날짜 데이터는 그대로 복사되어 채워진다.","1개의 숫자와 문자가 조합된 텍스트 데이터는 숫자만 1씩 증가하고 문자는 그대로 복사되어 채워진다.","숫자 데이터는 1씩 증가하면서 채워진다.","숫자가 입력된 두 셀을 블록 설정하여 채우기 핸들을 드래그하면 두 숫자가 반복하여 채워진다."],"id":"2020-1-B","e":"2020 1회 B형"},{"n":30,"s":2,"a":4,"p":"다음 중 아래 시트에 대한 각 수식의 결과값이 나머지 셋과 다른 것은?","c":["=SMALL(A1:G1,{3})","=AVERAGE(SMALL(A1:G1,{1;2;3;4;5}))","=LARGE(A1:G1,{5})","=SMALL(A1:G1,COLUMN(D1))"],"id":"2020-1-B","e":"2020 1회 B형"},{"n":31,"s":2,"a":4,"p":"아래 시트에서 주민등록번호의 여덟 번째 문자가 ‘1’ 또는 ‘3’이면 ‘남’, ‘2’ 또는 ‘4’이면 ‘여’로 성별 정보를 알 수 있다. 다음 중 성별을 계산하기 위한 [D2] 셀의 수식으로 옳지 않은 것은? (단, [F2:F5] 영역은 숫자 데이터임)","c":["=IF(OR(MID(C2, 8, 1)=\"2\", MID(C2, 8, 1)=\"4\"), \"여\", \"남\")","=CHOOSE(VALUE(MID(C2, 8, 1)), \"남\", \"여\", \"남\", \"여\")","=VLOOKUP(VALUE(MID(C2, 8, 1)), $F$2:$G$5, 2, 0)","=IF(MOD(VALUE(MID(C2, 8, 1)), 2)=0, \"남\", \"여\")"],"id":"2020-1-B","e":"2020 1회 B형"},{"n":32,"s":2,"a":3,"p":"다음 중 [개발 도구] 탭의 [컨트롤] 그룹에 대한 설명으로 옳지 않는 것은?","c":["컨트롤 종류에는 텍스트 상자, 목록 상자, 옵션 단추, 명령 단추 등이 있다.","ActiveX 컨트롤은 양식 컨트롤 보다 다양한 이벤트에 반응할 수 있지만, 양식 컨트롤보다 호환성은 낮다.","[디자인 모드] 상태에서는 양식 컨트롤과 ActiveX 컨트롤 모두 매크로 등 정해진 동작은 실행하지 않지만 컨트롤의 선택, 크기 조절, 이동 등의 작업을 할 수 있다.","양식 컨트롤의 ‘단추(양식 컨트롤)’를 클릭하거나 드래그 해서 추가하면 [매크로 지정] 대화상자가 자동으로 표시 된다."],"id":"2020-1-B","e":"2020 1회 B형"},{"n":33,"s":2,"a":2,"p":"다음 중 아래의 프로시저가 실행된 후 [A1] 셀에 입력 되는 값으로 옳은 것은? Sub 예제( ) Test = 0 Do Until Test > 10 Test = Test + 1 Loop Range(\"A1\").Value = Test End Sub","c":["10","11","0","55 컴퓨터활용능력 1급 B형 5/7"],"id":"2020-1-B","e":"2020 1회 B형"},{"n":34,"s":2,"a":2,"p":"다음 중 엑셀의 화면 확대/축소 작업에 관한 설명으로 옳지 않은 것은?","c":["문서의 확대/축소는 10%에서 400%까지 설정할 수 있다.","설정한 확대/축소 배율은 통합 문서의 모든 시트에 자동으로 적용된다.","화면의 확대/축소는 단지 화면에서 보이는 상태만을 확대/축소하는 것으로 인쇄 시 적용되지 않는다.","<Ctrl> 키를 누른 채 마우스의 스크롤을 위로 올리면 화면이 확대되고, 아래로 내리면 화면이 축소된다."],"id":"2020-1-B","e":"2020 1회 B형"},{"n":35,"s":2,"a":2,"p":"다음 중 인쇄 기능에 대한 설명으로 옳지 않은 것은?","c":["기본적으로 워크시트의 눈금선은 인쇄되지 않으나 인쇄 되도록 설정할 수 있다.","[페이지 설정] 대화상자의 [시트] 탭에서 ‘간단하게 인쇄’ 를 선택하면 셀의 테두리를 포함하여 인쇄할 수 있다.","[인쇄 미리 보기 및 인쇄] 화면을 표시하는 단축키는 <Ctrl> + <F2> 이다.","[인쇄 미리 보기 및 인쇄]에서 ‘여백 표시’를 선택한 경우 마우스로 여백을 변경할 수 있다."],"id":"2020-1-B","e":"2020 1회 B형"},{"n":36,"s":2,"a":3,"p":"다음 중 차트 도구의 [데이터 선택]에 대한 설명으로 옳지 않은 것은?","c":["[차트 데이터 범위]에서 차트에 사용하는 데이터 전체의 범위를 수정할 수 있다.","[행/열 전환]을 클릭하여 가로 (항목) 축의 데이터 계열과 범례 항목(계열)을 바꿀 수 있다.","범례에서 표시되는 데이터 계열의 순서를 바꿀 수 없다.","데이터 범위 내에 숨겨진 행이나 열의 데이터도 차트에 표시할 수 있다."],"id":"2020-1-B","e":"2020 1회 B형"},{"n":37,"s":2,"a":3,"p":"아래 시트에서 국적별 영화 장르의 편수를 계산하기 위해 [B12] 셀에 작성해야 할 배열수식으로 옳지 않은 것은?","c":["{=SUM(($D$2:$D$9=$A12) * ($E$2:$E$9=B$11))}","{=SUM(IF($D$2:$D$9=$A12, IF($E$2:$E$9=B$11, 1)))}","{=COUNT(($D$2:$D$9=$A12) * ($E$2:$E$9=B$11))}","{=COUNT(IF(($D$2:$D$9=$A12) * ($E$2:$E$9=B$11), 1))}"],"id":"2020-1-B","e":"2020 1회 B형"},{"n":38,"s":2,"a":3,"p":"다음 중 이름 상자에 대한 설명으로 옳지 않은 것은?","c":["<Ctrl> 키를 누르고 여러 개의 셀을 선택한 경우 마지막 선택한 셀 주소가 표시된다.","셀이나 셀 범위에 이름을 정의해 놓은 경우 이름이 표시 된다.","차트가 선택되어 있는 경우 차트의 종류가 표시된다.","수식을 작성 중인 경우 최근 사용한 함수 목록이 표시 된다."],"id":"2020-1-B","e":"2020 1회 B형"},{"n":39,"s":2,"a":2,"p":"다음 중 셀 영역을 선택한 후 상태 표시줄의 바로 가기 메뉴인 [상태 표시줄 사용자 지정]에서 선택할 수 있는 자동 계산에 해당되지 않는 것은?","c":["선택한 영역 중 숫자 데이터가 입력된 셀의 수","선택한 영역 중 문자 데이터가 입력된 셀의 수","선택한 영역 중 데이터가 입력된 셀의 수","선택한 영역의 합계, 평균, 최소값, 최대값"],"id":"2020-1-B","e":"2020 1회 B형"},{"n":40,"s":2,"a":3,"p":"다음 중 아래 데이터를 차트로 작성하여 사원별로 각 분기의 실적을 비교·분석하려는 경우 가장 비효율적인 차트는?","c":["누적 세로 막대형 차트","표식이 있는 꺾은선형","원형 대 가로 막대형","묶은 가로 막대형"],"id":"2020-1-B","e":"2020 1회 B형"},{"n":41,"s":3,"a":1,"p":"다음 중 데이터 보안 및 회복, 무결성, 병행 수행 제어 등 을 정의하는 데이터베이스 언어로 데이터베이스 관리자가 데이터 관리를 목적으로 주로 사용하는 언어는?","c":["데이터 제어어(DCL)","데이터 부속어(DSL)","데이터 정의어(DDL)","데이터 조작어(DML)"],"id":"2020-1-B","e":"2020 1회 B형"},{"n":42,"s":3,"a":1,"p":"다음 중 SQL 질의에 대한 설명으로 옳지 않은 것은?","c":["ORDER BY절 사용 시 정렬방식을 별도로 지정하지 않으면 기본 값은 ‘DESC’로 적용된다.","GROUP BY절은 특정 필드를 기준으로 그룹화 하여 검색할 때 사용한다.","FROM절에는 테이블 또는 쿼리 이름을 지정하며, WHERE절에는 조건을 지정한다.","SELECT DISTINCT문을 사용하면 중복 레코드를 제거 할 수 있다."],"id":"2020-1-B","e":"2020 1회 B형"},{"n":43,"s":3,"a":2,"p":"다음 중 Access 파일에 암호를 설정하는 방법으로 옳은 것은?","c":["[데이터베이스 압축 및 복구] 도구에서 파일 암호를 설정할 수 있다.","데이터베이스를 단독 사용 모드(단독으로 열기)로 열어야 파일 암호를 설정할 수 있다.","데이터베이스를 MDE 형식으로 저장한 후 파일을 열어야 파일 암호를 설정할 수 있다.","[Access 옵션] 창의 보안 센터에서 파일 암호를 설정 할 수 있다. 컴퓨터활용능력 1급 B형 6/7"],"id":"2020-1-B","e":"2020 1회 B형"},{"n":44,"s":3,"a":1,"p":"다음 중 아래 보고서에 대한 설명으로 옳지 않은 것은?","c":["‘모델명’ 필드를 기준으로 그룹이 설정되어 있다.","‘모델명’ 필드에는 ‘중복 내용 숨기기’ 속성을 ‘예’로 설정하였다.","지점별 소계가 표시된 텍스트 상자는 그룹 바닥글에 삽입하였다.","순번은 컨트롤 원본을 ‘=1’ 로 입력한 후 ‘누적 합계’ 속성을 ‘그룹’으로 설정하였다."],"id":"2020-1-B","e":"2020 1회 B형"},{"n":45,"s":3,"a":4,"p":"다음 중 보고서의 그룹화 및 정렬에 대한 설명으로 옳지 않은 것은?","c":["‘그룹’은 머리글과 같은 소계 및 요약 정보와 함께 표시 되는 레코드의 모음으로 그룹 머리글, 세부 레코드 및 그룹 바닥글로 구성된다.","그룹화 할 필드가 날짜 데이터이면 전체 값(기본), 일, 주, 월, 분기, 연도 중 선택한 기준으로 그룹화 할 수 있다.","Sum 함수를 사용하는 계산 컨트롤을 그룹 머리글에 추가하면 현재 그룹에 대한 합계를 표시할 수 있다.","필드나 식을 기준으로 최대 5단계까지 그룹화 할 수 있으며, 같은 필드나 식은 한 번씩만 그룹화 할 수 있다."],"id":"2020-1-B","e":"2020 1회 B형"},{"n":46,"s":3,"a":2,"p":"다음 중 보고서 작업 시 필드 목록 창에서 선택한 필드를 본문 영역에 추가할 때 자동으로 생성되는 컨트롤은?","c":["단추","텍스트 상자","하이퍼링크","언바운드 개체 틀"],"id":"2020-1-B","e":"2020 1회 B형"},{"n":47,"s":3,"a":1,"p":"다음 중 보고서의 보기 형태에 대한 설명으로 옳지 않은 것은?","c":["[보고서 보기]는 출력되는 보고서를 화면 출력용으로 보여주며 페이지를 구분하여 표시한다.","[디자인 보기]에서는 보고서에 삽입된 컨트롤의 속성, 맞춤, 위치 등을 설정할 수 있다.","[레이아웃 보기]는 출력될 보고서의 레이아웃을 보여주며 컨트롤의 크기 및 위치를 변경할 수도 있다.","[인쇄 미리 보기]에서는 종이에 출력되는 모양을 표시 하며 인쇄를 위한 페이지 설정이 용이하다."],"id":"2020-1-B","e":"2020 1회 B형"},{"n":48,"s":3,"a":4,"p":"다음 중 아래 SQL문으로 생성된 테이블에서의 레코드 작업에 대한 설명으로 옳지 않은 것은? (단, 고객과 계좌 간의 관계는 1:M이다.) CREATE TABLE 고객 (고객ID CHAR(20) NOT NULL, 고객명 CHAR(20) NOT NULL, 연락번호 CHAR(12), PRIMARY KEY (고객ID) ); CREATE TABLE 계좌 (계좌번호 CHAR(10) NOT NULL, 고객ID CHAR(20) NOT NULL, 잔액 INTEGER DEFAULT 0, PRIMARY KEY (계좌번호), FOREIGN KEY (고객ID) REFERENCES 고객 );","c":["<고객> 테이블에서 ‘고객ID’ 필드는 동일한 값을 입력 할 수 없다.","<계좌> 테이블에서 ‘계좌번호’ 필드는 반드시 입력해야 한다.","<고객> 테이블에서 ‘연락번호’ 필드는 원하는 값으로 수정하거나 생략할 수 있다.","<계좌> 테이블에서 ‘고객ID’ 필드는 동일한 값을 입력 할 수 없다."],"id":"2020-1-B","e":"2020 1회 B형"},{"n":49,"s":3,"a":1,"p":"다음 중 테이블에서 입력 마스크를 “LA09?”로 설정한 경우 입력할 수 없는 값은?","c":["AA111","A11","AA11","A111A"],"id":"2020-1-B","e":"2020 1회 B형"},{"n":50,"s":3,"a":4,"p":"다음 중 아래 <학생> 테이블에 대한 SQL문의 실행 결과로 옳은 것은? SELECT AVG([나이]) FROM 학생 WHERE 학년=\"SN\" GROUP BY 전공 HAVING COUNT(*) >= 2;","c":["21","22","23","24"],"id":"2020-1-B","e":"2020 1회 B형"},{"n":51,"s":3,"a":3,"p":"다음 중 선택 쿼리에서 사용자가 지정한 패턴과 일치하는 데이터를 찾고자 할 때 사용되는 연산자는?","c":["Match","Some","Like","Any 컴퓨터활용능력 1급 B형 7/7"],"id":"2020-1-B","e":"2020 1회 B형"},{"n":52,"s":3,"a":2,"p":"다음 중 위쪽 구역에 데이터시트를 표시하는 열 형식의 폼을 만들고, 아래쪽 구역에 선택한 레코드에 대한 정보를 수정하거나 입력할 수 있는 데이터시트 형식의 폼을 자동으로 만들어 주는 도구는?","c":["폼","폼 분할","여러 항목","폼 디자인"],"id":"2020-1-B","e":"2020 1회 B형"},{"n":53,"s":3,"a":1,"p":"다음 중 이벤트 프로시저에서 쿼리를 실행 모드로 여는 명령은?","c":["DoCmd.OpenQuery","DoCmd.SetQuery","DoCmd.QueryView","DoCmd.QueryTable"],"id":"2020-1-B","e":"2020 1회 B형"},{"n":54,"s":3,"a":1,"p":"다음 중 폼의 구성요소에 대한 설명으로 옳지 않은 것은?","c":["폼 머리글은 인쇄할 때 모든 페이지의 상단에 매번 표시된다.","하위 폼은 폼 안에 있는 또 하나의 폼을 의미한다.","폼 바닥글은 폼 요약 정보 등과 같이 각 레코드에 동일 하게 표시될 정보가 입력되는 구역이다.","본문은 사용할 실제 내용을 입력하는 구역으로 폼 보기 형식에 따라 하나의 레코드만 표시하거나 여러 개의 레코드를 표시한다."],"id":"2020-1-B","e":"2020 1회 B형"},{"n":55,"s":3,"a":3,"p":"다음 중 아래 <고객>과 <구매리스트> 테이블 관계에 참조 무결성이 항상 유지되도록 설정할 수 없는 경우는?","c":["<고객> 테이블의 ‘고객번호’ 필드 값이 <구매리스트> 테이블의 ‘고객번호’ 필드에 없는 경우","<고객> 테이블의 ‘고객번호’ 필드 값이 <구매리스트> 테이블의 ‘고객번호’ 필드에 하나만 있는 경우","<구매리스트> 테이블의 ‘고객번호’ 필드 값이 <고객> 테이블의 ‘고객번호’ 필드에 없는 경우","<고객> 테이블의 ‘고객번호’ 필드 값이 <구매리스트> 테이블의 ‘고객번호’ 필드에 두 개 이상 있는 경우"],"id":"2020-1-B","e":"2020 1회 B형"},{"n":56,"s":3,"a":1,"p":"다음 중 외부 데이터 가져오기 기능에 대한 설명으로 옳지 않은 것은?","c":["텍스트 파일을 가져와 기존 테이블의 레코드로 추가 하려는 경우 기본 키에 해당하는 필드의 값들이 고유한 값이 되도록 데이터를 수정하며 가져올 수 있다.","Excel 워크시트에서 정의된 이름의 영역을 Access의 새 테이블이나 기존 테이블에 데이터 복사본으로 만들 수 있다.","Access에서는 한 테이블에 256개 이상의 필드를 지원 하지 않으므로 원본 데이터는 열의 개수가 255개를 초과 하지 않아야 한다.","Excel 파일을 가져오는 경우 한 번에 하나의 워크시트만 가져올 수 있으므로 여러 워크시트에서 데이터를 가져 오려면 각 워크시트에 대해 가져오기 명령을 반복해야 한다."],"id":"2020-1-B","e":"2020 1회 B형"},{"n":57,"s":3,"a":1,"p":"다음 중 폼 바닥글의 텍스트 상자의 컨트롤 원본으로 <사원> 테이블에서 직급이 ‘부장’인 레코드들의 급여 평균을 구하는 함수식으로 옳은 것은?","c":["=DAVG(“[급여]”, “[사원]”, “[직급]=‘부장’”)","=DAVG(“[사원]”, “[급여]”, “[직급]=‘부장’”)","=AVG(“[급여]”, “[사원]”, “[직급]=‘부장’”)","=AVG(“[사원]”, “[급여]”, “[직급]=‘부장’”)"],"id":"2020-1-B","e":"2020 1회 B형"},{"n":58,"s":3,"a":4,"p":"다음 중 액세스의 매크로에 대한 설명으로 옳지 않은 것은?","c":["반복적으로 수행되는 작업을 자동화하여 간단히 처리할 수 있도록 하는 기능이다.","매크로 함수 또는 매크로 함수 집합으로 구성되며, 각 매크로 함수의 수행 방식을 제어하는 인수를 추가할 수 있다.","매크로를 이용하여 폼을 열고 닫거나 메시지 박스를 표시할 수도 있다.","매크로는 주로 컨트롤의 이벤트에 연결하여 사용하며, 폼 개체 내에서만 사용할 수 있다."],"id":"2020-1-B","e":"2020 1회 B형"},{"n":59,"s":3,"a":2,"p":"다음 중 폼 작성에 관한 설명으로 옳지 않은 것은?","c":["여러 개의 컨트롤을 선택하여 자동 정렬할 수 있다.","컨트롤의 탭 순서는 자동으로 화면 위에서 아래로 설정 된다.","사각형, 선 등의 도형 컨트롤을 삽입할 수 있다.","컨트롤 마법사를 사용하여 폼을 닫는 매크로를 실행 시키는 단추를 만들 수 있다."],"id":"2020-1-B","e":"2020 1회 B형"},{"n":60,"s":3,"a":4,"p":"다음 중 관계형 데이터베이스의 조인(JOIN)에 대한 설명으로 옳지 않은 것은?","c":["쿼리에 여러 테이블을 포함할 때는 조인을 사용하여 원하는 결과를 얻을 수 있다.","내부 조인은 조인되는 두 테이블에서 조인하는 필드가 일치하는 행만을 반환하려는 경우에 사용한다.","외부 조인은 조인되는 두 테이블에서 공통 값이 없는 데이터를 포함할지 여부를 지정할 수 있다.","조인에 사용되는 기준 필드의 데이터 형식은 다르거나 호환되지 않아도 가능하다. * 수고하셨습니다. 수험자 여러분의 좋은 결과를 기원합니다."],"id":"2020-1-B","e":"2020 1회 B형"}]},{"id":"2020-2-A","t":"2020 2회 A형","q":[{"n":1,"s":1,"a":4,"p":"다음 중 컴퓨터 및 정보기기에서 사용하는 펌웨어 (Firmware)에 관한 설명으로 옳은 것은?","c":["주로 하드디스크의 부트 레코드 부분에 저장된다.","인터프리터 방식으로 번역되어 실행된다.","운영체제의 일부로 입출력을 전담한다.","소프트웨어의 업그레이드만으로도 기능을 향상시킬 수 있다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":2,"s":1,"a":4,"p":"다음 중 수의 표현에 있어 진법에 대한 설명으로 옳지 않은 것은?","c":["16진수(Hexadecimal)는 0∼9까지의 숫자와 A∼F까지 문자로 표현하는 진법으로 한 자리수를 표현하는데 4개의 비트가 필요하다.","2진수, 8진수, 16진수를 10진수 실수(float)로 변환 하려면 정수 부분과 소수 부분을 나누어서 변환하려는 각 진수의 자리값과 자리의 지수승을 곱한 결과값을 모두 더하여 계산한다.","10진수(Decimal) 정수를 2진수, 8진수, 16진수로 변환 하려면 10진수 값을 변환할 진수로 나누어 더 이상 나눠지지 않을 때까지 나누고, 몫을 제외한 나머지를 역순으로 표시한다.","8진수를 16진수로 변환하려면 8진수를 뒤에서부터 2자리씩 자른 후 각각 16진수를 1자리로 계산한다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":3,"s":1,"a":1,"p":"다음 중 정보 보안을 위한 비밀키 암호화 기법의 설명으로 옳지 않은 것은?","c":["서로 다른 키로 데이터를 암호화하고 복호화 한다.","암호화와 복호화의 속도가 빠르다.","알고리즘이 단순하고 파일의 크기가 작다.","사용자의 증가에 따라 관리해야 할 키의 수가 상대적 으로 많아진다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":4,"s":1,"a":3,"p":"다음 중 시스템 보안을 위해 사용하는 방화벽(Firewall)에 대한 설명으로 적절하지 않은 것은?","c":["IP주소 및 포트번호를 이용하거나 사용자 인증을 기반 으로 접속을 차단하여 네트워크의 출입로를 단일화 한다.","‘명백히 허용되지 않은 것은 금지한다’라는 적극적 방어 개념을 가지고 있다.","방화벽을 운영하면 바이러스와 내/외부의 새로운 위험에 효과적으로 대처할 수 있다.","로그 정보를 통해 외부침입의 흔적을 찾아 역추적 할 수 있다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":5,"s":1,"a":4,"p":"다음 중 Windows 운영체제에서의 백업과 복원에 관한 설명으로 옳지 않은 것은?","c":["특정 날짜와 시간에 백업할 수 있도록 백업 주기를 예약할 수 있다.","Windows에서 백업에 사용되는 파일의 확장자는 .bkf이다.","백업 파일을 복원할 경우 복원 위치를 지정할 수 있다.","여러 파일이 백업되어 있는 경우 원하는 파일을 선택 하여 복원할 수 없다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":6,"s":1,"a":3,"p":"다음 중 스마트폰을 모뎀처럼 활용하는 방법으로, 컴퓨터나 노트북 등의 IT 기기를 스마트폰에 연결하여 무선 인터넷을 사용할 수 있게 하는 기능은?","c":["와이파이(WiFi)","블루투스(Bluetooth)","테더링(Tethering)","와이브로(WiBro)"],"id":"2020-2-A","e":"2020 2회 A형"},{"n":7,"s":1,"a":3,"p":"다음 중 네트워크 관련 장비로 브리지(Bridge)에 관한 설명으로 옳지 않은 것은?","c":["OSI 참조 모델의 데이터 링크 계층에 속한다.","두 개의 근거리통신망을 상호 접속할 수 있도록 하는 통신망 연결 장치이다.","통신 프로토콜을 변환하여 네트워크를 확장한다.","통신량을 조절하여 데이터가 다른 곳으로 가지 않도록 한다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":8,"s":1,"a":3,"p":"다음 중 인터넷 기반 기술을 이용하여 기업들이 외부 보안을 유지한 상태에서 협력 업체 간의 효율적인 업무처리를 위해 사용하는 네트워크로 옳은 것은?","c":["인트라넷(Intranet)","원거리 통신망(WAN)","엑스트라넷(Extranet)","근거리 통신망(LAN)"],"id":"2020-2-A","e":"2020 2회 A형"},{"n":9,"s":1,"a":2,"p":"다음 중 TCP/IP 프로토콜에서 IP 프로토콜의 개요 및 기능에 관한 설명으로 옳은 것은?","c":["메시지를 송/수신자의 주소와 정보로 묶어 패킷 단위로 나눈다.","패킷 주소를 해석하고 경로를 결정하여 다음 호스트로 전송한다.","전송 데이터의 흐름을 제어하고 데이터의 에러를 검사 한다.","OSI 7계층에서 전송 계층에 해당한다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":10,"s":1,"a":4,"p":"다음 중 디지털 콘텐츠의 생성·거래·전달·관리 등 전체 과정을 관리할 수 있는 기술로 멀티미디어 프레임 워크의 MPEG 표준은?","c":["MPEG-1","MPEG-3","MPEG-7","MPEG-21"],"id":"2020-2-A","e":"2020 2회 A형"},{"n":11,"s":1,"a":4,"p":"다음 중 GIF 파일 형식에 대한 설명으로 옳지 않은 것은?","c":["인터넷 표준 그래픽 형식으로, 8비트 컬러를 사용하여 256색만 지원한다.","간단한 애니메이션 표현이 가능하다.","색상의 무손실 압축 기술을 사용한다.","벡터 방식으로 이미지를 표현한다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":12,"s":1,"a":2,"p":"다음 중 Windows의 [제어판] - [장치 및 프린터]에 표시되지 않는 것은?","c":["사용자 컴퓨터","하드디스크 드라이브와 사운드 카드","컴퓨터의 USB 포트에 연결하는 모든 장치","컴퓨터에 연결된 호환 네트워크 장치"],"id":"2020-2-A","e":"2020 2회 A형"},{"n":13,"s":1,"a":2,"p":"다음 중 컴퓨터의 제어장치에 있는 부호기(Encoder) 레지스터에 관한 설명으로 옳은 것은?","c":["명령 레지스터에 있는 명령어를 해독한다.","해독된 명령어에 따라 각 장치로 보낼 제어 신호를 생성한다.","다음 순서에 실행할 명령어의 주기억장치 주소를 기억 한다.","뺄셈연산을 위해 음수로 변환한다. 컴퓨터활용능력 1급 A형 3/8"],"id":"2020-2-A","e":"2020 2회 A형"},{"n":14,"s":1,"a":4,"p":"다음 중 Windows에서 바로 가기 아이콘에 관한 설명 으로 옳지 않은 것은?","c":["바로 가기 아이콘을 실행하면 연결된 원본 파일이 실행 된다.","파일, 폴더뿐만 아니라 디스크 드라이브나 프린터에도 바로 가기 아이콘을 만들 수 있다.","일반 아이콘과 비교하여 왼쪽 아랫부분에 화살표가 포함되어 표시된다.","하나의 바로 가기 아이콘에 여러 개의 원본 파일을 연결할 수 있다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":15,"s":1,"a":4,"p":"다음 중 Windows에서 파일이나 폴더, 프린터, 드라이브 등 컴퓨터 자원의 공유에 관한 설명으로 옳지 않은 것은?","c":["공유 폴더에 대한 접근 권한은 사용자에 따라 다르게 설정할 수 있다.","탐색기의 주소 표시줄에 '\\\\localhost'를 입력하면 네트워크를 통해 공유한 파일이나 폴더를 확인할 수 있다.","탐색기의 공유 기능을 이용하면 파일이나 폴더를 쉽게 다른 사용자와 공유할 수 있다.","공유한 파일명 뒤에 ‘$’를 붙이면 네트워크의 다른 사용자가 해당 파일을 사용하고 있는지 여부를 바로 확인할 수 있다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":16,"s":1,"a":2,"p":"다음 중 출력장치인 디스플레이 어댑터와 모니터에 관련된 용어의 설명으로 옳지 않은 것은?","c":["픽셀(Pixel): 화면을 이루는 최소 단위로서 같은 크기의 화면에서 픽셀 수가 많을수록 해상도가 높아진다.","해상도(Resolution): 모니터 화면의 픽셀 수와 관련이 있으며 픽셀 수가 많을수록 표시할 수 있는 색상의 수가 증가한다.","점 간격(Dot Pitch): 픽셀들 사이의 공간을 나타내는 것으로 간격이 가까울수록 영상은 선명하다.","재생률(Refresh Rate): 픽셀들이 밝게 빛나는 것을 유지하기 위한 것으로, 재생률이 높을수록 모니터의 깜빡임이 줄어든다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":17,"s":1,"a":4,"p":"다음 중 컴퓨터에서 사용하는 기억장치에 관한 설명으로 옳지 않은 것은?","c":["플래시(Flash) 메모리는 비휘발성 기억장치로 주로 디지털 카메라나 MP3, 개인용 정보 단말기, USB 드라이브 등 휴대용 기기에서 대용량 정보를 저장하는 용도로 사용된다.","하드디스크 인터페이스 방식은 EIDE, SATA, SCSI 방식 등이 있다.","캐시(Cache) 메모리는 CPU와 주기억장치 사이에 위치 하여 두 장치간의 속도 차이를 줄여 컴퓨터의 처리 속도를 빠르게 하기 위한 메모리이다.","연관(Associative) 메모리는 보조기억장치를 마치 주기억장치와 같이 사용하여 실제 주기억 장치 용량보다 기억용량을 확대하여 사용하는 방법이다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":18,"s":1,"a":3,"p":"다음 중 패치(Patch) 버전 소프트웨어에 관한 설명으로 옳은 것은?","c":["정식으로 대가를 지불하고 사용하는 소프트웨어이다.","홍보용으로 사용 기간이나 기능에 제한을 둔 소프트웨어 이다.","오류 수정이나 성능 향상을 위해 프로그램 일부를 변경해주는 소프트웨어이다.","정식 프로그램 출시 전에 테스트용으로 제작되어 일반인 에게 공개하는 소프트웨어이다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":19,"s":1,"a":1,"p":"다음 중 컴퓨터에서 사용하는 압축 프로그램에 관한 설명 으로 옳지 않은 것은?","c":["압축한 파일을 모아 재압축을 반복하면 파일 크기를 계속 줄일 수 있다.","여러 개의 파일을 압축하면 하나의 파일로 생성되어 파일 관리를 용이하게 할 수 있다.","대부분의 압축 프로그램에는 분할 압축이나 암호 설정 기능이 있다.","파일의 전송시간과 비용을 절약하고, 디스크 공간을 효율적으로 사용할 수 있다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":20,"s":1,"a":3,"p":"다음 중 Windows에서 바탕 화면의 바로 가기 메뉴에 관한 설명으로 옳지 않은 것은?","c":["바탕 화면에서 <Shift> + <F10> 키를 누르면 바로 가기 메뉴가 표시된다.","바탕 화면에 폴더나 텍스트 문서, 압축 파일 등을 새로 만들 수 있다.","삭제된 컴퓨터, 휴지통, 네트워크 등의 바탕 화면 아이콘을 다시 표시할 수 있다.","아이콘의 정렬 기준을 변경하거나 아이콘의 크기를 변경하여 볼 수 있다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":21,"s":2,"a":1,"p":"다음 중 피벗 테이블에 대한 설명으로 옳지 않은 것은?","c":["피벗 테이블 보고서를 작성한 후 원본 데이터를 수정 하면 피벗 테이블 보고서에 자동으로 반영된다.","[피벗 테이블 필드 목록]에서 보고서에 추가할 필드 선택 시 데이터 형식이 텍스트이거나 논리값인 필드를 선택하여 ‘행 레이블’ 영역에 추가한다.","값 영역에 추가된 필드가 2개 이상이면 ∑ 값 필드가 열 레이블 또는 행 레이블 영역에 추가된다.","열 레이블/행 레이블 단추를 클릭하여 레이블 필터나 값 필터를 설정할 수 있다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":22,"s":2,"a":3,"p":"아래 그림과 같이 설정한 상태에서 [매크로 기록] 대화 상자의 [확인] 단추를 누른다. [A2:A6] 범위를 선택한 후 글꼴 스타일을 굵게 지정하고 [기록 중지]를 눌러 ‘서식’ 매크로의 작성을 완료하였다. 다음 중 매크로 작성 후 [C1] 셀을 선택하고 ‘서식’ 매크로를 실행한 결과로 옳은 것은?","c":["[A2:A6] 영역의 글꼴 스타일이 굵게 지정된다.","[A1] 셀만 글꼴 스타일이 굵게 지정된다.","[C2:C6] 영역의 글꼴 스타일이 굵게 지정된다.","[C1] 셀만 글꼴 스타일이 굵게 지정된다. 컴퓨터활용능력 1급 A형 4/8"],"id":"2020-2-A","e":"2020 2회 A형"},{"n":23,"s":2,"a":3,"p":"다음 중 아래 그림과 같은 시나리오 요약 보고서에 대한 설명으로 옳지 않은 것은?","c":["‘호황’과 ‘불황’ 두 개의 시나리오로 작성한 시나리오 요약 보고서는 새 워크시트에 표시된다.","원본 데이터에 ‘냉장고판매’, ‘세탁기판매’, ‘예상 판매금액’으로 이름을 정의한 셀이 있다.","원본 데이터에서 변경 셀의 현재 값을 수정하면 시나리오 요약 보고서가 자동으로 업데이트된다.","시나리오 요약 보고서 내의 모든 내용은 수정 가능하며, 자동으로 설정된 윤곽도 지울 수 있다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":24,"s":2,"a":1,"p":"다음 중 아래 시트에서 사원명이 두 글자이면서 실적이 전체 실적의 평균을 초과하는 데이터를 검색할 때, 고급 필터의 조건으로 옳은 것은?","c":["사원명 실적조건 =\"=??\" =$B2>AVERAGE($B$2:$B$9)","사원명 실적 =\"=??\" =$B2&“>AVERAGE($B$2:$B$9)”","사원명 실적 =LEN($A2)=2 =$B2>AVERAGE($B$2:$B$9)","사원명 실적조건 =\"=**\" =$B2>AVERAGE($B$2:$B$9)"],"id":"2020-2-A","e":"2020 2회 A형"},{"n":25,"s":2,"a":4,"p":"다음 중 데이터가 입력되어 있는 연속된 셀 범위를 선택하는 방법으로 옳지 않은 것은?","c":["첫 번째 셀을 클릭한 후 <Ctrl> + <Shift> + <방향키> 를 눌러 선택 영역을 확장한다.","첫 번째 셀을 클릭한 후 <Shift> 키를 누른 상태에서 범위의 마지막 셀을 클릭한다.","첫 번째 셀을 클릭한 후 <F8> 키를 누른 후 <방향키> 를 눌러 선택 영역을 확장한다.","첫 번째 셀을 클릭한 후 <Ctrl> 키를 누른 상태에서 <방향키>를 눌러 선택 영역을 확장한다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":26,"s":2,"a":1,"p":"다음 중 [외부 데이터 가져오기] 기능에 대한 설명으로 옳지 않은 것은?","c":["텍스트 파일은 구분 기호나 일정한 너비로 분리된 모든 열을 엑셀로 가져오기 때문에 일부 열만 가져올 수는 없다.","액세스 파일은 표, 피벗 테이블, 워크시트의 특정 위치 등으로 다양하게 불러올 수 있다.","웹 상의 데이터 중 일부를 워크시트로 가져오고, 새로 고침 기능을 이용하여 최신 데이터로 업데이트할 수 있다.","기타 원본의 Microsoft Query 기능을 이용하면 외부 데이터베이스에서 가져올 데이터의 추출 조건을 설정 하여 원하는 데이터만 가져올 수 있다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":27,"s":2,"a":1,"p":"다음 중 [찾기 및 바꾸기] 대화상자에 대한 설명으로 옳지 않은 것은?","c":["찾을 내용에 ‘*수정*’, 바꿀 내용에 ‘*변경*’으로 입력하고, [모두 바꾸기] 단추를 클릭하면 ‘수정’ 이라는 모든 글자를 ‘*변경*’으로 바꾼다.","‘=A1*B1’과 같은 수식을 검색하려면 찾는 위치를 ‘수식’으로 선택한 후 찾을 내용에 ‘=A1~*B1’으로 입력한다.","찾을 내용과 바꿀 내용은 입력하지 않고, 찾을 서식과 바꿀 서식으로 설정 할 수 있다.","셀포인터 위치를 기준으로 앞에 위치한 데이터를 찾으려면 <Shift> 키를 누른 상태에서 [다음 찾기] 단추를 클릭한다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":28,"s":2,"a":4,"p":"다음 중 엑셀에서 날짜 데이터의 입력 방법에 대한 설명으로 옳지 않은 것은?","c":["날짜 데이터는 하이픈(-)이나 슬래시(/)를 이용하여 년, 월, 일을 구분한다.","날짜의 연도를 생략하고 월과 일만 입력하면 자동으로 현재 연도가 추가된다.","날짜의 연도를 두 자리로 입력할 때 연도가 30 이상 이면 1900년대로 인식하고, 29 이하이면 2000년대로 인식한다.","<Ctrl> + <Shift> + <;> 키를 누르면 오늘 날짜가 입력된다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":29,"s":2,"a":1,"p":"다음 중 아래 차트에 대한 설명으로 옳지 않은 것은?","c":["계열 옵션에서 ‘간격 너비’가 0%로 설정되어 있다.","범례 표지 없이 데이터 표가 표시되어 있다.","‘1월’, ‘2월’, ‘3월’ 계열에 오차 막대가 표시 되어 있다.","‘1분기 합계’ 계열은 ‘보조 축’으로 지정되어 있다. 컴퓨터활용능력 1급 A형 5/8"],"id":"2020-2-A","e":"2020 2회 A형"},{"n":30,"s":2,"a":3,"p":"다음 중 서식 코드를 셀의 사용자 지정 표시 형식으로 설정한 경우 입력 데이터와 표시 결과가 옳지 않은 것은?","c":["ⓐ","ⓑ","ⓒ","ⓓ"],"id":"2020-2-A","e":"2020 2회 A형"},{"n":31,"s":2,"a":2,"p":"다음 중 매크로 편집 및 삭제에 대한 설명으로 옳지 않은 것은?","c":["[매크로] 대화상자에서 편집할 매크로를 선택하고 [편집] 단추를 클릭하면 Visual Basic 편집기를 실행 할 수 있다.","<Alt> + <F8> 키를 눌러 Visual Basic 편집기를 실행 하면 매크로를 수정할 수 있다.","PERSONAL.XLSB 파일을 삭제하면 통합 문서에 있는 모든 매크로를 삭제할 수 있다.","Visual Basic 편집기에서 삭제할 매크로의 코딩 부분을 범위로 지정한 뒤 <Delete> 키를 눌러 여러 매크로를 한 번에 삭제할 수 있다 ."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":32,"s":2,"a":1,"p":"다음 중 아래의 워크시트에서 수식의 결과로 ‘부사장’을 출력하지 않는 것은?","c":["=CHOOSE(CELL(\"row\",B3), C2, C3, C4, C5, C6)","=CHOOSE(TYPE(B4), C2, C3, C4, C5, C6)","=OFFSET(A1:A6,2,2,1,1)","=INDEX(A2:D6,MATCH(A3, A2:A6, 0), 3)"],"id":"2020-2-A","e":"2020 2회 A형"},{"n":33,"s":2,"a":2,"p":"다음 중 아래의 워크시트에서 작성한 수식으로 결과 값이 다른 것은?","c":["=SMALL(B1:B3, COLUMN(C3))","=SMALL(A1:B3, AVERAGE({1;2;3;4;5}))","=LARGE(A1:B3, ROW(A1))","=LARGE(A1:C3, AVERAGE({1;2;3;4;5}))"],"id":"2020-2-A","e":"2020 2회 A형"},{"n":34,"s":2,"a":3,"p":"다음 중 통합 문서에 대한 설명으로 옳지 않은 것은?","c":["시트 보호는 통합 문서 전체가 아닌 특정 시트만을 보호한다.","공유된 통합 문서는 여러 사용자가 동시에 변경 및 병합할 수 있다.","통합 문서 보호 설정 시 암호를 지정하면 워크시트에 입력된 내용을 수정할 수 없다.","사용자가 워크시트를 추가, 삭제하거나 숨겨진 워크시트 를 표시하지 못하도록 통합 문서의 구조를 잠글 수 있다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":35,"s":2,"a":3,"p":"아래 시트에서 각 부서마다 직위별로 종합점수의 합계를 구하려고 한다. 다음 중 [B17] 셀에 입력된 수식으로 옳은 것은?","c":["{=SUMIFS($E$2:$E$13, $A$2:$A$13, $A$17,$B$2:$B$13, $B$16)}","{=SUM(($A$2:$A$13=A17) * ($B$2:$B$13=B16) * $E$2:$E$13)}","{=SUM(($A$2:$A$13=$A17) * ($B$2:$B$13=B$16) * $E$2:$E$13)}","{=SUM(($A$2:$A$13=A$17) * ($B$2:$B$13=$B16) * $E$2:$E$13)}"],"id":"2020-2-A","e":"2020 2회 A형"},{"n":36,"s":2,"a":3,"p":"다음 중 셀에 수식을 입력하는 방법에 대한 설명으로 옳지 않은 것은?","c":["통합 문서의 여러 워크시트에 있는 동일한 셀 범위 데이터를 이용하려면 수식에서 3차원 참조를 사용한다.","계산할 셀 범위를 선택하여 수식을 입력한 후 <Ctrl> + <Enter> 키를 누르면 선택한 영역에 수식을 한 번에 채울 수 있다.","수식을 입력한 후 결과 값이 상수로 입력되게 하려면 수식을 입력한 후 바로 <Alt> + <F9> 키를 누른다.","배열 상수에는 숫자나 텍스트 외에 ‘TRUE’, ‘FALSE’ 등의 논리값 또는 ‘#N/A’와 같은 오류 값도 포함될 수 있다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":37,"s":2,"a":1,"p":"다음 중 아래 그림 [보기]탭 [창]그룹의 각 명령에 대한 설명으로 옳지 않은 것은?","c":["[새 창]을 클릭하면 새로운 빈 통합문서가 표시된다.","[모두 정렬]은 현재 열려 있는 통합문서를 바둑판식, 계단식, 가로, 세로 등 4가지 형태로 배열한다.","[숨기기]는 현재 활성화된 통합문서 창을 보이지 않도록 숨긴다.","[나누기]를 클릭하면 워크시트를 최대 4개의 창으로 분할하여 멀리 떨어져 있는 여러 부분을 한 번에 볼 수 있다. 컴퓨터활용능력 1급 A형 6/8"],"id":"2020-2-A","e":"2020 2회 A형"},{"n":38,"s":2,"a":3,"p":"다음 중 엑셀의 상태 표시줄에 대한 설명으로 옳지 않은 것은?","c":["상태 표시줄에서 워크시트의 보기 상태를 기본 보기, 페이지 레이아웃 보기, 페이지 나누기 미리 보기 중 선택하여 변경할 수 있다.","상태 표시줄에는 확대/축소 슬라이더가 기본적으로 표시된다.","상태 표시줄의 바로 가기 메뉴를 이용하여 셀의 특정 범위에 대한 이름을 정의할 수 있다.","상태 표시줄은 현재의 작업 상태에 대한 기본적인 정보가 표시되는 곳이다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":39,"s":2,"a":3,"p":"다음 중 차트의 편집에 대한 설명으로 옳지 않은 것은?","c":["차트와 연결된 워크시트의 데이터에 열을 추가하면 차트에 자동적으로 반영되지 않는다.","차트 크기를 조정하면 새로운 크기에 가장 적합하도록 차트 내의 텍스트의 크기 등이 자동적으로 조정된다.","차트에 적용된 원본 데이터의 행이나 열을 숨겨도 차트에는 반영되지 않는다.","데이터 계열의 순서가 변경되면 범례의 순서도 자동으로 변경된다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":40,"s":2,"a":3,"p":"다음 중 엑셀의 인쇄 기능에 대한 설명으로 옳지 않은 것은?","c":["차트만 제외하고 인쇄하기 위해서는 [차트 영역 서식] 대화상자에서 ‘개체 인쇄’의 체크를 해제한다.","시트에 표시된 오류 값을 제외하고 인쇄하기 위해서는 [페이지 설정] 대화 상자에서 ‘셀 오류 표시’를 ‘<공백>’으로 선택한다.","인쇄 내용을 페이지의 가운데에 맞춰 인쇄하려면 [페이지 설정] 대화 상자에서 ‘문서에 맞게 배율 조정’을 체크한다.","인쇄되는 모든 페이지에 특정 행을 반복하려면 [페이지 설정] 대화 상자에서 ‘인쇄 제목’의 ‘반복할 행’에 열 레이블이 포함된 행의 참조를 입력한다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":41,"s":3,"a":2,"p":"다음 중 관계형 데이터베이스 모델에 대한 설명으로 옳지 않은 것은?","c":["도메인(Domain)은 하나의 애트리뷰트(Attribute)가 취할 수 있는 같은 타입의 원자값들의 집합이다.","한 릴레이션(Relation)에 포함된 튜플(Tuple)들은 모두 상이하며, 튜플(Tuple) 사이에는 순서가 있다.","튜플(Tuple)의 수를 카디널리티(Cardinality), 애트 리뷰트(Attribute)의 수를 디그리(Degree)라고 한다.","애트리뷰트(Attribute)는 데이터베이스를 구성하는 가장 작은 논리적 단위이며, 파일 구조상의 데이터 필드에 해당된다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":42,"s":3,"a":4,"p":"다음 중 입력 마스크 설정에 사용하는 사용자 정의 입력 마스크 기호에 대한 설명으로 옳은 것은?","c":["9: 소문자로 변환",">: 숫자나 공백을 입력받도록 설정","<: 영문 대문자로 변환하여 입력받도록 설정","L: 영문자와 한글만 입력받도록 설정"],"id":"2020-2-A","e":"2020 2회 A형"},{"n":43,"s":3,"a":2,"p":"다음 중 데이터를 입력 또는 삭제 시 이상(anomaly) 현상이 일어나지 않도록 데이터베이스를 설계하기 위한 기술을 의미하는 용어는?","c":["자동화","정규화","순서화","추상화"],"id":"2020-2-A","e":"2020 2회 A형"},{"n":44,"s":3,"a":4,"p":"다음 중 [관계 편집] 대화 상자에 대한 설명으로 옳지 않은 것은?","c":["관계를 구성하는 어느 한쪽의 테이블 또는 필드 및 쿼리를 변경할 수 있다.","조인 유형을 내부 조인, 왼쪽 우선 외부 조인, 오른쪽 우선 외부 조인 중에서 선택할 수 있다.","‘항상 참조 무결성 유지’를 선택한 경우 ‘관련 필드 모두 업데이트’와 ‘관련 레코드 모두 삭제’ 옵션을 선택할 수 있다.","관계의 종류를 일대다, 다대다, 일대일 중에서 선택할 수 있다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":45,"s":3,"a":4,"p":"다음 중 테이블의 필드 속성 설정 시 사용하는 인덱스에 관한 설명으로 옳지 않은 것은?","c":["인덱스를 설정하면 레코드의 검색과 정렬 속도가 빨라 진다.","인덱스를 설정하면 레코드의 추가, 수정, 삭제 속도는 느려진다.","데이터 형식이 OLE 개체인 필드에는 인덱스를 설정할 수 없다.","인덱스는 한 개의 필드에만 설정 가능하므로 주로 기본 키에 설정한다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":46,"s":3,"a":1,"p":"다음 중 테이블의 [디자인 보기]에서 설정 가능한 작업에 해당하지 않는 것은?","c":["폼 필터를 적용하여 조건에 맞는 레코드만 표시할 수 있다.","필드의 '설명'에 입력한 내용은 테이블 구조에 영향을 미치지 않고, 상태 표시줄에 표시된다.","컨트롤 표시 속성은 텍스트 상자, 목록 상자, 콤보 상자 중 선택할 수 있다.","한 개 이상의 필드를 선택하여 기본 키로 설정할 수 있다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":47,"s":3,"a":1,"p":"아래와 같이 관계가 설정된 데이터베이스에 [Customer] 테이블에는 고객번호가 1004인 레코드만 있고, [Artist] 테이블에는 작가이름이 CAT인 레코드만 있다. 다음 중 이 데이터베이스에서 실행 가능한 SQL 문은? (단, SQL문에 입력되는 데이터 형식은 모두 올바르다고 간주함)","c":["INSERT INTO Artist VALUES (‘ACE’, ‘한국’, Null, Null);","INSERT INTO CINTA (고객번호, 작가이름) VALUES (1004, ‘ACE’);","INSERT INTO Customer (고객번호, 고객이름) VALUES (1004, ‘ACE’);","INSERT INTO CINTA VALUES (1234, ‘CAT’, ‘유화’); 컴퓨터활용능력 1급 A형 7/8"],"id":"2020-2-A","e":"2020 2회 A형"},{"n":48,"s":3,"a":1,"p":"다음 중 주어진 [학생] 테이블을 참조하여 아래의 SQL 문을 실행한 결과로 옳은 것은? SELECT AVG(나이) FROM 학생 WHERE 전공 NOT IN (‘수학’, ‘회계’); 학번 전공 학년 나이 100 국사 4 21 150 회계 2 19 200 수학 3 30 250 국사 3 31 300 회계 4 25 350 수학 2 19 400 국사 1 23 [학생] 테이블","c":["25","23","21","19"],"id":"2020-2-A","e":"2020 2회 A형"},{"n":49,"s":3,"a":3,"p":"아래와 같이 조회할 고객의 최소 나이를 입력받아 검색 하는 매개 변수 쿼리를 작성하려고 한다. 다음 중 'Age' 필드의 조건식으로 옳은 것은?","c":[">={조회할 최소 나이 입력}",">=“조회할 최소 나이 입력”",">=[조회할 최소 나이 입력]",">=(조회할 최소 나이 입력)"],"id":"2020-2-A","e":"2020 2회 A형"},{"n":50,"s":3,"a":3,"p":"다음 중 아래의 이벤트 프로시저에 대한 설명으로 옳지 않은 것은? Private Sub cmd재고_Click() txt재고수량 = txt입고량 - txt총주문량 DoCmd.OpenReport \"제품별재고현황\", _ acViewDesign, , \"제품번호 = '\"& cmb조회 & \"'\" End Sub","c":["'cmd재고' 컨트롤을 클릭했을 때 실행된다.","'txt재고수량' 컨트롤에는 'txt입고량' 컨트롤에 표시 되는 값에서 'txt총주문량' 컨트롤에 표시되는 값을 차감한 값으로 표시된다.","'제품별재고현황' 보고서가 즉시 프린터로 출력된다.","'제품별재고현황' 보고서가 출력될 때 '제품번호' 필드 값이 'cmb조회' 컨트롤 값과 일치하는 데이터만 표시된다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":51,"s":3,"a":2,"p":"다음 중 주어진 [Customer] 테이블을 참조하여 아래의 SQL문을 실행한 결과로 옳은 것은? SELECT Count(*) FROM (SELECT Distinct City From Customer);","c":["3","5","7","9"],"id":"2020-2-A","e":"2020 2회 A형"},{"n":52,"s":3,"a":2,"p":"다음 중 보고서에서 ‘텍스트 상자’ 컨트롤의 속성 설정에 대한 설명으로 옳지 않은 것은?","c":["‘상태 표시줄 텍스트’ 속성은 컨트롤을 선택했을 때 상태 표시줄에 표시할 메시지를 설정한다.","‘컨트롤 원본’ 속성에서 함수나 수식 사용 시 문자는 작은 따옴표(‘), 필드명이나 컨트롤 이름은 큰따옴표 (“)를 사용하여 구분한다.","‘사용 가능’ 속성은 컨트롤에 포커스를 이동시킬 수 있는지의 여부를 설정한다.","'중복 내용 숨기기' 속성은 데이터가 이전 레코드와 같을 때 컨트롤의 숨김 여부를 설정한다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":53,"s":3,"a":2,"p":"다음 중 보고서에서 [페이지 번호] 대화 상자를 이용한 페이지 번호 설정에 대한 설명으로 옳지 않은 것은?","c":["첫 페이지에만 페이지 번호가 표시되거나 표시되지 않도록 설정할 수 있다.","페이지 번호의 표시 위치를 ‘페이지 위쪽’, ‘페이지 아래쪽’, ‘페이지 양쪽’ 중 선택할 수 있다.","페이지 번호의 형식을 ‘N 페이지’와 ‘N/M 페이지’ 중 선택할 수 있다.","[페이지 번호] 대화 상자를 열 때마다 페이지 번호 표시를 위한 수식이 입력된 텍스트 상자가 자동으로 삽입된다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":54,"s":3,"a":3,"p":"다음 중 서류봉투에 초대장을 넣어 발송하려는 경우 우편물에 사용할 수신자의 주소를 프린트하기에 가장 적합한 보고서는?","c":["업무 문서 양식 보고서","우편 엽서 보고서","레이블 보고서","크로스탭 보고서"],"id":"2020-2-A","e":"2020 2회 A형"},{"n":55,"s":3,"a":3,"p":"다음 중 폼 작성에 대한 설명으로 옳지 않은 것은?","c":["[폼 디자인 도구]의 [디자인] 탭에서 [컨트롤 마법사 사용] 여부를 선택할 수 있다.","[레이블] 컨트롤은 마법사를 이용한 만들기가 제공되지 않으며, 레이블 컨트롤을 추가한 후 내용을 입력하지 않으면 추가된 레이블 컨트롤이 자동으로 사라진다.","[텍스트 상자] 컨트롤을 지칭하는 이름은 중복 설정이 가능하다.","[단추] 컨트롤은 명령 단추 마법사를 이용하여 다양한 매크로 함수를 제공한다. 컴퓨터활용능력 1급 A형 8/8"],"id":"2020-2-A","e":"2020 2회 A형"},{"n":56,"s":3,"a":1,"p":"다음 중 폼의 모달 속성에 관한 설명으로 옳지 않은 것은?","c":["폼이 열려 있는 경우 다른 화면을 선택할 수 있다.","VBA 코드를 이용하여 대화 상자의 모달 속성을 지정할 수 있다.","폼이 모달 대화 상자이면 디자인 보기로 전환 후 데이터 시트 보기로 전환이 가능하다.","사용자 지정 대화 상자의 작성이 가능하다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":57,"s":3,"a":4,"p":"다음 중 보고서에 대한 설명으로 옳지 않은 것은?","c":["보고서에 포함할 필드가 모두 한 테이블에 있는 경우 해당 테이블을 레코드 원본으로 사용한다.","둘 이상의 테이블을 이용하여 보고서를 작성하는 경우 쿼리를 만들어 레코드 원본으로 사용한다.","‘보고서’ 도구를 사용하면 정보를 입력하지 않아도 바로 보고서가 생성되므로 매우 쉽고 빠르게 보고서를 만들 수 있다.","‘보고서 마법사’를 이용하는 경우 필드 선택은 여러 개의 테이블 또는 하나의 쿼리에서만 가능하며, 데이터 그룹화 및 정렬 방법을 지정할 수도 있다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":58,"s":3,"a":3,"p":"다음 중 분할 표시 폼에 대한 설명으로 옳지 않은 것은?","c":["분할 표시 폼은 [만들기] 탭의 [폼] 그룹에서 [기타 폼] - [폼 분할]을 클릭하여 만들 수 있다.","분할 표시 폼은 데이터시트 보기와 폼 보기를 동시에 표시하기 기능이며, 이 두 보기는 같은 데이터 원본에 연결되어 있어 항상 상호 동기화된다.","분할 표시 폼을 만든 후에는 컨트롤의 크기 조정은 할 수 없으나, 새로운 필드의 추가는 가능하다.","폼 속성 창의 ‘분할 표시 폼 방향’ 항목을 이용하여 폼의 위쪽, 아래쪽, 왼쪽, 오른쪽 등 데이터시트가 표시되는 위치를 설정할 수 있다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":59,"s":3,"a":1,"p":"다음 중 매크로 함수에 대한 설명으로 옳지 않은 것은?","c":["FindRecord 함수는 필드, 컨트롤, 속성 등의 값을 설정한다.","ApplyFilter 함수는 테이블이나 쿼리로부터 레코드를 필터링한다.","OpenReport 함수는 작성된 보고서를 호출하여 실행한다.","MessageBox 함수는 메시지 상자를 통해 경고나 알림 등의 정보를 표시한다."],"id":"2020-2-A","e":"2020 2회 A형"},{"n":60,"s":3,"a":4,"p":"다음 중 하위 폼에 대한 설명으로 옳지 않은 것은?","c":["기본 폼과 하위 폼을 연결할 필드의 데이터 형식은 같거나 호환되어야 한다.","본 폼 내에 삽입된 다른 폼을 하위 폼이라 한다.","일대다 관계가 설정되어 있는 테이블들을 효과적으로 표시하기 위해 사용된다.","‘폼 분할’ 도구를 이용하여 폼을 생성하면 하위 폼 컨트롤이 자동으로 삽입된다. * 수고하셨습니다. 수험자 여러분의 좋은 결과를 기원합니다."],"id":"2020-2-A","e":"2020 2회 A형"}]},{"id":"2020-2-B","t":"2020 2회 B형","q":[{"n":1,"s":1,"a":3,"p":"다음 중 시스템 보안을 위해 사용하는 방화벽(Firewall)에 대한 설명으로 적절하지 않은 것은?","c":["IP주소 및 포트번호를 이용하거나 사용자 인증을 기반 으로 접속을 차단하여 네트워크의 출입로를 단일화 한다.","‘명백히 허용되지 않은 것은 금지한다’라는 적극적 방어 개념을 가지고 있다.","방화벽을 운영하면 바이러스와 내/외부의 새로운 위험에 효과적으로 대처할 수 있다.","로그 정보를 통해 외부침입의 흔적을 찾아 역추적 할 수 있다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":2,"s":1,"a":4,"p":"다음 중 Windows 운영체제에서의 백업과 복원에 관한 설명으로 옳지 않은 것은?","c":["특정 날짜와 시간에 백업할 수 있도록 백업 주기를 예약할 수 있다.","Windows에서 백업에 사용되는 파일의 확장자는 .bkf이다.","백업 파일을 복원할 경우 복원 위치를 지정할 수 있다.","여러 파일이 백업되어 있는 경우 원하는 파일을 선택 하여 복원할 수 없다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":3,"s":1,"a":4,"p":"다음 중 컴퓨터 및 정보기기에서 사용하는 펌웨어 (Firmware)에 관한 설명으로 옳은 것은?","c":["주로 하드디스크의 부트 레코드 부분에 저장된다.","인터프리터 방식으로 번역되어 실행된다.","운영체제의 일부로 입출력을 전담한다.","소프트웨어의 업그레이드만으로도 기능을 향상시킬 수 있다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":4,"s":1,"a":4,"p":"다음 중 수의 표현에 있어 진법에 대한 설명으로 옳지 않은 것은?","c":["16진수(Hexadecimal)는 0∼9까지의 숫자와 A∼F까지 문자로 표현하는 진법으로 한 자리수를 표현하는데 4개의 비트가 필요하다.","2진수, 8진수, 16진수를 10진수 실수(float)로 변환 하려면 정수 부분과 소수 부분을 나누어서 변환하려는 각 진수의 자리값과 자리의 지수승을 곱한 결과값을 모두 더하여 계산한다.","10진수(Decimal) 정수를 2진수, 8진수, 16진수로 변환 하려면 10진수 값을 변환할 진수로 나누어 더 이상 나눠지지 않을 때까지 나누고, 몫을 제외한 나머지를 역순으로 표시한다.","8진수를 16진수로 변환하려면 8진수를 뒤에서부터 2자리씩 자른 후 각각 16진수를 1자리로 계산한다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":5,"s":1,"a":1,"p":"다음 중 정보 보안을 위한 비밀키 암호화 기법의 설명으로 옳지 않은 것은?","c":["서로 다른 키로 데이터를 암호화하고 복호화 한다.","암호화와 복호화의 속도가 빠르다.","알고리즘이 단순하고 파일의 크기가 작다.","사용자의 증가에 따라 관리해야 할 키의 수가 상대적 으로 많아진다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":6,"s":1,"a":4,"p":"다음 중 GIF 파일 형식에 대한 설명으로 옳지 않은 것은?","c":["인터넷 표준 그래픽 형식으로, 8비트 컬러를 사용하여 256색만 지원한다.","간단한 애니메이션 표현이 가능하다.","색상의 무손실 압축 기술을 사용한다.","벡터 방식으로 이미지를 표현한다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":7,"s":1,"a":2,"p":"다음 중 Windows의 [제어판] - [장치 및 프린터]에 표시되지 않는 것은?","c":["사용자 컴퓨터","하드디스크 드라이브와 사운드 카드","컴퓨터의 USB 포트에 연결하는 모든 장치","컴퓨터에 연결된 호환 네트워크 장치"],"id":"2020-2-B","e":"2020 2회 B형"},{"n":8,"s":1,"a":2,"p":"다음 중 컴퓨터의 제어장치에 있는 부호기(Encoder) 레지스터에 관한 설명으로 옳은 것은?","c":["명령 레지스터에 있는 명령어를 해독한다.","해독된 명령어에 따라 각 장치로 보낼 제어 신호를 생성한다.","다음 순서에 실행할 명령어의 주기억장치 주소를 기억 한다.","뺄셈연산을 위해 음수로 변환한다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":9,"s":1,"a":3,"p":"다음 중 스마트폰을 모뎀처럼 활용하는 방법으로, 컴퓨터나 노트북 등의 IT 기기를 스마트폰에 연결하여 무선 인터넷을 사용할 수 있게 하는 기능은?","c":["와이파이(WiFi)","블루투스(Bluetooth)","테더링(Tethering)","와이브로(WiBro)"],"id":"2020-2-B","e":"2020 2회 B형"},{"n":10,"s":1,"a":3,"p":"다음 중 네트워크 관련 장비로 브리지(Bridge)에 관한 설명으로 옳지 않은 것은?","c":["OSI 참조 모델의 데이터 링크 계층에 속한다.","두 개의 근거리통신망을 상호 접속할 수 있도록 하는 통신망 연결 장치이다.","통신 프로토콜을 변환하여 네트워크를 확장한다.","통신량을 조절하여 데이터가 다른 곳으로 가지 않도록 한다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":11,"s":1,"a":3,"p":"다음 중 인터넷 기반 기술을 이용하여 기업들이 외부 보안을 유지한 상태에서 협력 업체 간의 효율적인 업무처리를 위해 사용하는 네트워크로 옳은 것은?","c":["인트라넷(Intranet)","원거리 통신망(WAN)","엑스트라넷(Extranet)","근거리 통신망(LAN)"],"id":"2020-2-B","e":"2020 2회 B형"},{"n":12,"s":1,"a":2,"p":"다음 중 TCP/IP 프로토콜에서 IP 프로토콜의 개요 및 기능에 관한 설명으로 옳은 것은?","c":["메시지를 송/수신자의 주소와 정보로 묶어 패킷 단위로 나눈다.","패킷 주소를 해석하고 경로를 결정하여 다음 호스트로 전송한다.","전송 데이터의 흐름을 제어하고 데이터의 에러를 검사 한다.","OSI 7계층에서 전송 계층에 해당한다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":13,"s":1,"a":4,"p":"다음 중 디지털 콘텐츠의 생성·거래·전달·관리 등 전체 과정을 관리할 수 있는 기술로 멀티미디어 프레임 워크의 MPEG 표준은?","c":["MPEG-1","MPEG-3","MPEG-7","MPEG-21 컴퓨터활용능력 1급 B형 3/8"],"id":"2020-2-B","e":"2020 2회 B형"},{"n":14,"s":1,"a":4,"p":"다음 중 컴퓨터에서 사용하는 기억장치에 관한 설명으로 옳지 않은 것은?","c":["플래시(Flash) 메모리는 비휘발성 기억장치로 주로 디지털 카메라나 MP3, 개인용 정보 단말기, USB 드라이브 등 휴대용 기기에서 대용량 정보를 저장하는 용도로 사용된다.","하드디스크 인터페이스 방식은 EIDE, SATA, SCSI 방식 등이 있다.","캐시(Cache) 메모리는 CPU와 주기억장치 사이에 위치 하여 두 장치간의 속도 차이를 줄여 컴퓨터의 처리 속도를 빠르게 하기 위한 메모리이다.","연관(Associative) 메모리는 보조기억장치를 마치 주기억장치와 같이 사용하여 실제 주기억장치 용량보다 기억용량을 확대하여 사용하는 방법이다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":15,"s":1,"a":3,"p":"다음 중 패치(Patch) 버전 소프트웨어에 관한 설명으로 옳은 것은?","c":["정식으로 대가를 지불하고 사용하는 소프트웨어이다.","홍보용으로 사용 기간이나 기능에 제한을 둔 소프트웨어 이다.","오류 수정이나 성능 향상을 위해 프로그램 일부를 변경해주는 소프트웨어이다.","정식 프로그램 출시 전에 테스트용으로 제작되어 일반인 에게 공개하는 소프트웨어이다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":16,"s":1,"a":4,"p":"다음 중 Windows에서 바로 가기 아이콘에 관한 설명 으로 옳지 않은 것은?","c":["바로 가기 아이콘을 실행하면 연결된 원본 파일이 실행 된다.","파일, 폴더뿐만 아니라 디스크 드라이브나 프린터에도 바로 가기 아이콘을 만들 수 있다.","일반 아이콘과 비교하여 왼쪽 아랫부분에 화살표가 포함되어 표시된다.","하나의 바로 가기 아이콘에 여러 개의 원본 파일을 연결할 수 있다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":17,"s":1,"a":4,"p":"다음 중 Windows에서 파일이나 폴더, 프린터, 드라이브 등 컴퓨터 자원의 공유에 관한 설명으로 옳지 않은 것은?","c":["공유 폴더에 대한 접근 권한은 사용자에 따라 다르게 설정할 수 있다.","탐색기의 주소 표시줄에 '\\\\localhost'를 입력하면 네트워크를 통해 공유한 파일이나 폴더를 확인할 수 있다.","탐색기의 공유 기능을 이용하면 파일이나 폴더를 쉽게 다른 사용자와 공유할 수 있다.","공유한 파일명 뒤에 ‘$’를 붙이면 네트워크의 다른 사용자가 해당 파일을 사용하고 있는지 여부를 바로 확인할 수 있다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":18,"s":1,"a":2,"p":"다음 중 출력장치인 디스플레이 어댑터와 모니터에 관련된 용어의 설명으로 옳지 않은 것은?","c":["픽셀(Pixel): 화면을 이루는 최소 단위로서 같은 크기의 화면에서 픽셀 수가 많을수록 해상도가 높아진다.","해상도(Resolution): 모니터 화면의 픽셀 수와 관련이 있으며 픽셀 수가 많을수록 표시할 수 있는 색상의 수가 증가한다.","점 간격(Dot Pitch): 픽셀들 사이의 공간을 나타내는 것으로 간격이 가까울수록 영상은 선명하다.","재생률(Refresh Rate): 픽셀들이 밝게 빛나는 것을 유지하기 위한 것으로, 재생률이 높을수록 모니터의 깜빡임이 줄어든다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":19,"s":1,"a":1,"p":"다음 중 컴퓨터에서 사용하는 압축 프로그램에 관한 설명 으로 옳지 않은 것은?","c":["압축한 파일을 모아 재압축을 반복하면 파일 크기를 계속 줄일 수 있다.","여러 개의 파일을 압축하면 하나의 파일로 생성되어 파일 관리를 용이하게 할 수 있다.","대부분의 압축 프로그램에는 분할 압축이나 암호 설정 기능이 있다.","파일의 전송시간과 비용을 절약하고, 디스크 공간을 효율적으로 사용할 수 있다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":20,"s":1,"a":3,"p":"다음 중 Windows에서 바탕 화면의 바로 가기 메뉴에 관한 설명으로 옳지 않은 것은?","c":["바탕 화면에서 <Shift> + <F10> 키를 누르면 바로 가기 메뉴가 표시된다.","바탕 화면에 폴더나 텍스트 문서, 압축 파일 등을 새로 만들 수 있다.","삭제된 컴퓨터, 휴지통, 네트워크 등의 바탕 화면 아이콘을 다시 표시할 수 있다.","아이콘의 정렬 기준을 변경하거나 아이콘의 크기를 변경하여 볼 수 있다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":21,"s":2,"a":3,"p":"아래 그림과 같이 설정한 상태에서 [매크로 기록] 대화 상자의 [확인] 단추를 누른다. [A2:A6] 범위를 선택한 후 글꼴 스타일을 굵게 지정하고 [기록 중지]를 눌러 ‘서식’ 매크로의 작성을 완료하였다. 다음 중 매크로 작성 후 [C1] 셀을 선택하고 ‘서식’ 매크로를 실행한 결과로 옳은 것은?","c":["[A2:A6] 영역의 글꼴 스타일이 굵게 지정된다.","[A1] 셀만 글꼴 스타일이 굵게 지정된다.","[C2:C6] 영역의 글꼴 스타일이 굵게 지정된다.","[C1] 셀만 글꼴 스타일이 굵게 지정된다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":22,"s":2,"a":1,"p":"다음 중 피벗 테이블에 대한 설명으로 옳지 않은 것은?","c":["피벗 테이블 보고서를 작성한 후 원본 데이터를 수정 하면 피벗 테이블 보고서에 자동으로 반영된다.","[피벗 테이블 필드 목록]에서 보고서에 추가할 필드 선택 시 데이터 형식이 텍스트이거나 논리값인 필드를 선택하여 ‘행 레이블’ 영역에 추가한다.","값 영역에 추가된 필드가 2개 이상이면 ∑ 값 필드가 열 레이블 또는 행 레이블 영역에 추가된다.","열 레이블/행 레이블 단추를 클릭하여 레이블 필터나 값 필터를 설정할 수 있다. 컴퓨터활용능력 1급 B형 4/8"],"id":"2020-2-B","e":"2020 2회 B형"},{"n":23,"s":2,"a":3,"p":"다음 중 아래 그림과 같은 시나리오 요약 보고서에 대한 설명으로 옳지 않은 것은?","c":["‘호황’과 ‘불황’ 두 개의 시나리오로 작성한 시나리오 요약 보고서는 새 워크시트에 표시된다.","원본 데이터에 ‘냉장고판매’, ‘세탁기판매’, ‘예상 판매금액’으로 이름을 정의한 셀이 있다.","원본 데이터에서 변경 셀의 현재 값을 수정하면 시나리오 요약 보고서가 자동으로 업데이트된다.","시나리오 요약 보고서 내의 모든 내용은 수정 가능하며, 자동으로 설정된 윤곽도 지울 수 있다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":24,"s":2,"a":4,"p":"다음 중 데이터가 입력되어 있는 연속된 셀 범위를 선택하는 방법으로 옳지 않은 것은?","c":["첫 번째 셀을 클릭한 후 <Ctrl> + <Shift> + <방향키> 를 눌러 선택 영역을 확장한다.","첫 번째 셀을 클릭한 후 <Shift> 키를 누른 상태에서 범위의 마지막 셀을 클릭한다.","첫 번째 셀을 클릭한 후 <F8> 키를 누른 후 <방향키> 를 눌러 선택 영역을 확장한다.","첫 번째 셀을 클릭한 후 <Ctrl> 키를 누른 상태에서 <방향키>를 눌러 선택 영역을 확장한다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":25,"s":2,"a":1,"p":"다음 중 아래 시트에서 사원명이 두 글자이면서 실적이 전체 실적의 평균을 초과하는 데이터를 검색할 때, 고급 필터의 조건으로 옳은 것은?","c":["사원명 실적조건 =\"=??\" =$B2>AVERAGE($B$2:$B$9)","사원명 실적 =\"=??\" =$B2&“>AVERAGE($B$2:$B$9)”","사원명 실적 =LEN($A2)=2 =$B2>AVERAGE($B$2:$B$9)","사원명 실적조건 =\"=**\" =$B2>AVERAGE($B$2:$B$9)"],"id":"2020-2-B","e":"2020 2회 B형"},{"n":26,"s":2,"a":4,"p":"다음 중 엑셀에서 날짜 데이터의 입력 방법에 대한 설명으로 옳지 않은 것은?","c":["날짜 데이터는 하이픈(-)이나 슬래시(/)를 이용하여 년, 월, 일을 구분한다.","날짜의 연도를 생략하고 월과 일만 입력하면 자동으로 현재 연도가 추가된다.","날짜의 연도를 두 자리로 입력할 때 연도가 30 이상 이면 1900년대로 인식하고, 29 이하이면 2000년대로 인식한다.","<Ctrl> + <Shift> + <;> 키를 누르면 오늘 날짜가 입력된다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":27,"s":2,"a":1,"p":"다음 중 아래 차트에 대한 설명으로 옳지 않은 것은?","c":["계열 옵션에서 ‘간격 너비’가 0%로 설정되어 있다.","범례 표지 없이 데이터 표가 표시되어 있다.","‘1월’, ‘2월’, ‘3월’ 계열에 오차 막대가 표시 되어 있다.","‘1분기 합계’ 계열은 ‘보조 축’으로 지정되어 있다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":28,"s":2,"a":1,"p":"다음 중 [외부 데이터 가져오기] 기능에 대한 설명으로 옳지 않은 것은?","c":["텍스트 파일은 구분 기호나 일정한 너비로 분리된 모든 열을 엑셀로 가져오기 때문에 일부 열만 가져올 수는 없다.","액세스 파일은 표, 피벗 테이블, 워크시트의 특정 위치 등으로 다양하게 불러올 수 있다.","웹 상의 데이터 중 일부를 워크시트로 가져오고, 새로 고침 기능을 이용하여 최신 데이터로 업데이트할 수 있다.","기타 원본의 Microsoft Query 기능을 이용하면 외부 데이터베이스에서 가져올 데이터의 추출 조건을 설정 하여 원하는 데이터만 가져올 수 있다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":29,"s":2,"a":1,"p":"다음 중 [찾기 및 바꾸기] 대화상자에 대한 설명으로 옳지 않은 것은?","c":["찾을 내용에 ‘*수정*’, 바꿀 내용에 ‘*변경*’으로 입력하고, [모두 바꾸기] 단추를 클릭하면 ‘수정’ 이라는 모든 글자를 ‘*변경*’으로 바꾼다.","‘=A1*B1’과 같은 수식을 검색하려면 찾는 위치를 ‘수식’으로 선택한 후 찾을 내용에 ‘=A1~*B1’으로 입력한다.","찾을 내용과 바꿀 내용은 입력하지 않고, 찾을 서식과 바꿀 서식으로 설정 할 수 있다.","셀포인터 위치를 기준으로 앞에 위치한 데이터를 찾으려면 <Shift> 키를 누른 상태에서 [다음 찾기] 단추를 클릭한다. 컴퓨터활용능력 1급 B형 5/8"],"id":"2020-2-B","e":"2020 2회 B형"},{"n":30,"s":2,"a":2,"p":"다음 중 아래의 워크시트에서 작성한 수식으로 결과 값이 다른 것은?","c":["=SMALL(B1:B3, COLUMN(C3))","=SMALL(A1:B3, AVERAGE({1;2;3;4;5}))","=LARGE(A1:B3, ROW(A1))","=LARGE(A1:C3, AVERAGE({1;2;3;4;5}))"],"id":"2020-2-B","e":"2020 2회 B형"},{"n":31,"s":2,"a":3,"p":"다음 중 통합 문서에 대한 설명으로 옳지 않은 것은?","c":["시트 보호는 통합 문서 전체가 아닌 특정 시트만을 보호한다.","공유된 통합 문서는 여러 사용자가 동시에 변경 및 병합할 수 있다.","통합 문서 보호 설정 시 암호를 지정하면 워크시트에 입력된 내용을 수정할 수 없다.","사용자가 워크시트를 추가, 삭제하거나 숨겨진 워크시트를 표시하지 못하도록 통합 문서의 구조를 잠글 수 있다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":32,"s":2,"a":3,"p":"다음 중 서식 코드를 셀의 사용자 지정 표시 형식으로 설정한 경우 입력 데이터와 표시 결과가 옳지 않은 것은?","c":["ⓐ","ⓑ","ⓒ","ⓓ"],"id":"2020-2-B","e":"2020 2회 B형"},{"n":33,"s":2,"a":2,"p":"다음 중 매크로 편집 및 삭제에 대한 설명으로 옳지 않은 것은?","c":["[매크로] 대화상자에서 편집할 매크로를 선택하고 [편집] 단추를 클릭하면 Visual Basic 편집기를 실행 할 수 있다.","<Alt> + <F8> 키를 눌러 Visual Basic 편집기를 실행 하면 매크로를 수정할 수 있다.","PERSONAL.XLSB 파일을 삭제하면 통합 문서에 있는 모든 매크로를 삭제할 수 있다.","Visual Basic 편집기에서 삭제할 매크로의 코딩 부분을 범위로 지정한 뒤 <Delete> 키를 눌러 여러 매크로를 한 번에 삭제할 수 있다 ."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":34,"s":2,"a":1,"p":"다음 중 아래의 워크시트에서 수식의 결과로 ‘부사장’을 출력하지 않는 것은?","c":["=CHOOSE(CELL(\"row\",B3), C2, C3, C4, C5, C6)","=CHOOSE(TYPE(B4), C2, C3, C4, C5, C6)","=OFFSET(A1:A6,2,2,1,1)","=INDEX(A2:D6,MATCH(A3, A2:A6, 0), 3)"],"id":"2020-2-B","e":"2020 2회 B형"},{"n":35,"s":2,"a":3,"p":"다음 중 셀에 수식을 입력하는 방법에 대한 설명으로 옳지 않은 것은?","c":["통합 문서의 여러 워크시트에 있는 동일한 셀 범위 데이터를 이용하려면 수식에서 3차원 참조를 사용한다.","계산할 셀 범위를 선택하여 수식을 입력한 후 <Ctrl> + <Enter> 키를 누르면 선택한 영역에 수식을 한 번에 채울 수 있다.","수식을 입력한 후 결과 값이 상수로 입력되게 하려면 수식을 입력한 후 바로 <Alt> + <F9> 키를 누른다.","배열 상수에는 숫자나 텍스트 외에 ‘TRUE’, ‘FALSE’ 등의 논리값 또는 ‘#N/A’와 같은 오류 값도 포함될 수 있다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":36,"s":2,"a":1,"p":"다음 중 아래 그림 [보기]탭 [창]그룹의 각 명령에 대한 설명으로 옳지 않은 것은?","c":["[새 창]을 클릭하면 새로운 빈 통합문서가 표시된다.","[모두 정렬]은 현재 열려 있는 통합문서를 바둑판식, 계단식, 가로, 세로 등 4가지 형태로 배열한다.","[숨기기]는 현재 활성화된 통합문서 창을 보이지 않도록 숨긴다.","[나누기]를 클릭하면 워크시트를 최대 4개의 창으로 분할하여 멀리 떨어져 있는 여러 부분을 한 번에 볼 수 있다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":37,"s":2,"a":3,"p":"아래 시트에서 각 부서마다 직위별로 종합점수의 합계를 구하려고 한다. 다음 중 [B17] 셀에 입력된 수식으로 옳은 것은?","c":["{=SUMIFS($E$2:$E$13, $A$2:$A$13, $A$17,$B$2:$B$13, $B$16)}","{=SUM(($A$2:$A$13=A17) * ($B$2:$B$13=B16) * $E$2:$E$13)}","{=SUM(($A$2:$A$13=$A17) * ($B$2:$B$13=B$16) * $E$2:$E$13)}","{=SUM(($A$2:$A$13=A$17) * ($B$2:$B$13=$B16) * $E$2:$E$13)} 컴퓨터활용능력 1급 B형 6/8"],"id":"2020-2-B","e":"2020 2회 B형"},{"n":38,"s":2,"a":3,"p":"다음 중 엑셀의 상태 표시줄에 대한 설명으로 옳지 않은 것은?","c":["상태 표시줄에서 워크시트의 보기 상태를 기본 보기, 페이지 레이아웃 보기, 페이지 나누기 미리 보기 중 선택하여 변경할 수 있다.","상태 표시줄에는 확대/축소 슬라이더가 기본적으로 표시된다.","상태 표시줄의 바로 가기 메뉴를 이용하여 셀의 특정 범위에 대한 이름을 정의할 수 있다.","상태 표시줄은 현재의 작업 상태에 대한 기본적인 정보가 표시되는 곳이다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":39,"s":2,"a":3,"p":"다음 중 차트의 편집에 대한 설명으로 옳지 않은 것은?","c":["차트와 연결된 워크시트의 데이터에 열을 추가하면 차트에 자동적으로 반영되지 않는다.","차트 크기를 조정하면 새로운 크기에 가장 적합하도록 차트 내의 텍스트의 크기 등이 자동적으로 조정된다.","차트에 적용된 원본 데이터의 행이나 열을 숨겨도 차트에는 반영되지 않는다.","데이터 계열의 순서가 변경되면 범례의 순서도 자동으로 변경된다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":40,"s":2,"a":3,"p":"다음 중 엑셀의 인쇄 기능에 대한 설명으로 옳지 않은 것은?","c":["차트만 제외하고 인쇄하기 위해서는 [차트 영역 서식] 대화상자에서 ‘개체 인쇄’의 체크를 해제한다.","시트에 표시된 오류 값을 제외하고 인쇄하기 위해서는 [페이지 설정] 대화 상자에서 ‘셀 오류 표시’를 ‘<공백>’으로 선택한다.","인쇄 내용을 페이지의 가운데에 맞춰 인쇄하려면 [페이지 설정] 대화 상자에서 ‘문서에 맞게 배율 조정’을 체크한다.","인쇄되는 모든 페이지에 특정 행을 반복하려면 [페이지 설정] 대화 상자에서 ‘인쇄 제목’의 ‘반복할 행’에 열 레이블이 포함된 행의 참조를 입력한다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":41,"s":3,"a":4,"p":"다음 중 입력 마스크 설정에 사용하는 사용자 정의 입력 마스크 기호에 대한 설명으로 옳은 것은?","c":["9: 소문자로 변환",">: 숫자나 공백을 입력받도록 설정","<: 영문 대문자로 변환하여 입력받도록 설정","L: 영문자와 한글만 입력받도록 설정"],"id":"2020-2-B","e":"2020 2회 B형"},{"n":42,"s":3,"a":2,"p":"다음 중 관계형 데이터베이스 모델에 대한 설명으로 옳지 않은 것은?","c":["도메인(Domain)은 하나의 애트리뷰트(Attribute)가 취할 수 있는 같은 타입의 원자값들의 집합이다.","한 릴레이션(Relation)에 포함된 튜플(Tuple)들은 모두 상이하며, 튜플(Tuple) 사이에는 순서가 있다.","튜플(Tuple)의 수를 카디널리티(Cardinality), 애트 리뷰트(Attribute)의 수를 디그리(Degree)라고 한다.","애트리뷰트(Attribute)는 데이터베이스를 구성하는 가장 작은 논리적 단위이며, 파일 구조상의 데이터 필드에 해당된다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":43,"s":3,"a":1,"p":"다음 중 테이블의 [디자인 보기]에서 설정 가능한 작업에 해당하지 않는 것은?","c":["폼 필터를 적용하여 조건에 맞는 레코드만 표시할 수 있다.","필드의 '설명'에 입력한 내용은 테이블 구조에 영향을 미치지 않고, 상태 표시줄에 표시된다.","컨트롤 표시 속성은 텍스트 상자, 목록 상자, 콤보 상자 중 선택할 수 있다.","한 개 이상의 필드를 선택하여 기본 키로 설정할 수 있다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":44,"s":3,"a":1,"p":"아래와 같이 관계가 설정된 데이터베이스에 [Customer] 테이블에는 고객번호가 1004인 레코드만 있고, [Artist] 테이블에는 작가이름이 CAT인 레코드만 있다. 다음 중 이 데이터베이스에서 실행 가능한 SQL 문은? (단, SQL문에 입력되는 데이터 형식은 모두 올바르다고 간주함)","c":["INSERT INTO Artist VALUES (‘ACE’, ‘한국’, Null, Null);","INSERT INTO CINTA (고객번호, 작가이름) VALUES (1004, ‘ACE’);","INSERT INTO Customer (고객번호, 고객이름) VALUES (1004, ‘ACE’);","INSERT INTO CINTA VALUES (1234, ‘CAT’, ‘유화’);"],"id":"2020-2-B","e":"2020 2회 B형"},{"n":45,"s":3,"a":2,"p":"다음 중 데이터를 입력 또는 삭제 시 이상(anomaly) 현상이 일어나지 않도록 데이터베이스를 설계하기 위한 기술을 의미하는 용어는?","c":["자동화","정규화","순서화","추상화"],"id":"2020-2-B","e":"2020 2회 B형"},{"n":46,"s":3,"a":4,"p":"다음 중 [관계 편집] 대화 상자에 대한 설명으로 옳지 않은 것은?","c":["관계를 구성하는 어느 한쪽의 테이블 또는 필드 및 쿼리를 변경할 수 있다.","조인 유형을 내부 조인, 왼쪽 우선 외부 조인, 오른쪽 우선 외부 조인 중에서 선택할 수 있다.","‘항상 참조 무결성 유지’를 선택한 경우 ‘관련 필드 모두 업데이트’와 ‘관련 레코드 모두 삭제’ 옵션을 선택할 수 있다.","관계의 종류를 일대다, 다대다, 일대일 중에서 선택할 수 있다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":47,"s":3,"a":4,"p":"다음 중 테이블의 필드 속성 설정 시 사용하는 인덱스에 관한 설명으로 옳지 않은 것은?","c":["인덱스를 설정하면 레코드의 검색과 정렬 속도가 빨라 진다.","인덱스를 설정하면 레코드의 추가, 수정, 삭제 속도는 느려진다.","데이터 형식이 OLE 개체인 필드에는 인덱스를 설정할 수 없다.","인덱스는 한 개의 필드에만 설정 가능하므로 주로 기본 키에 설정한다. 컴퓨터활용능력 1급 B형 7/8"],"id":"2020-2-B","e":"2020 2회 B형"},{"n":48,"s":3,"a":3,"p":"다음 중 아래의 이벤트 프로시저에 대한 설명으로 옳지 않은 것은? Private Sub cmd재고_Click() txt재고수량 = txt입고량 - txt총주문량 DoCmd.OpenReport \"제품별재고현황\", _ acViewDesign, , \"제품번호 = '\"& cmb조회 & \"'\" End Sub","c":["'cmd재고' 컨트롤을 클릭했을 때 실행된다.","'txt재고수량' 컨트롤에는 'txt입고량' 컨트롤에 표시 되는 값에서 'txt총주문량' 컨트롤에 표시되는 값을 차감한 값으로 표시된다.","'제품별재고현황' 보고서가 즉시 프린터로 출력된다.","'제품별재고현황' 보고서가 출력될 때 '제품번호' 필드 값이 'cmb조회' 컨트롤 값과 일치하는 데이터만 표시된다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":49,"s":3,"a":1,"p":"다음 중 주어진 [학생] 테이블을 참조하여 아래의 SQL 문을 실행한 결과로 옳은 것은? SELECT AVG(나이) FROM 학생 WHERE 전공 NOT IN (‘수학’, ‘회계’); 학번 전공 학년 나이 100 국사 4 21 150 회계 2 19 200 수학 3 30 250 국사 3 31 300 회계 4 25 350 수학 2 19 400 국사 1 23 [학생] 테이블","c":["25","23","21","19"],"id":"2020-2-B","e":"2020 2회 B형"},{"n":50,"s":3,"a":3,"p":"아래와 같이 조회할 고객의 최소 나이를 입력받아 검색 하는 매개 변수 쿼리를 작성하려고 한다. 다음 중 'Age' 필드의 조건식으로 옳은 것은?","c":[">={조회할 최소 나이 입력}",">=“조회할 최소 나이 입력”",">=[조회할 최소 나이 입력]",">=(조회할 최소 나이 입력)"],"id":"2020-2-B","e":"2020 2회 B형"},{"n":51,"s":3,"a":2,"p":"다음 중 보고서에서 [페이지 번호] 대화 상자를 이용한 페이지 번호 설정에 대한 설명으로 옳지 않은 것은?","c":["첫 페이지에만 페이지 번호가 표시되거나 표시되지 않도록 설정할 수 있다.","페이지 번호의 표시 위치를 ‘페이지 위쪽’, ‘페이지 아래쪽’, ‘페이지 양쪽’ 중 선택할 수 있다.","페이지 번호의 형식을 ‘N 페이지’와 ‘N/M 페이지’ 중 선택할 수 있다.","[페이지 번호] 대화 상자를 열 때마다 페이지 번호 표시를 위한 수식이 입력된 텍스트 상자가 자동으로 삽입된다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":52,"s":3,"a":3,"p":"다음 중 서류봉투에 초대장을 넣어 발송하려는 경우 우편물에 사용할 수신자의 주소를 프린트하기에 가장 적합한 보고서는?","c":["업무 문서 양식 보고서","우편 엽서 보고서","레이블 보고서","크로스탭 보고서"],"id":"2020-2-B","e":"2020 2회 B형"},{"n":53,"s":3,"a":3,"p":"다음 중 폼 작성에 대한 설명으로 옳지 않은 것은?","c":["[폼 디자인 도구]의 [디자인] 탭에서 [컨트롤 마법사 사용] 여부를 선택할 수 있다.","[레이블] 컨트롤은 마법사를 이용한 만들기가 제공되지 않으며, 레이블 컨트롤을 추가한 후 내용을 입력하지 않으면 추가된 레이블 컨트롤이 자동으로 사라진다.","[텍스트 상자] 컨트롤을 지칭하는 이름은 중복 설정이 가능하다.","[단추] 컨트롤은 명령 단추 마법사를 이용하여 다양한 매크로 함수를 제공한다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":54,"s":3,"a":2,"p":"다음 중 주어진 [Customer] 테이블을 참조하여 아래의 SQL문을 실행한 결과로 옳은 것은? SELECT Count(*) FROM (SELECT Distinct City From Customer);","c":["3","5","7","9"],"id":"2020-2-B","e":"2020 2회 B형"},{"n":55,"s":3,"a":2,"p":"다음 중 보고서에서 ‘텍스트 상자’ 컨트롤의 속성 설정에 대한 설명으로 옳지 않은 것은?","c":["‘상태 표시줄 텍스트’ 속성은 컨트롤을 선택했을 때 상태 표시줄에 표시할 메시지를 설정한다.","‘컨트롤 원본’ 속성에서 함수나 수식 사용 시 문자는 작은 따옴표(‘), 필드명이나 컨트롤 이름은 큰따옴표 (“)를 사용하여 구분한다.","‘사용 가능’ 속성은 컨트롤에 포커스를 이동시킬 수 있는지의 여부를 설정한다.","'중복 내용 숨기기' 속성은 데이터가 이전 레코드와 같을 때 컨트롤의 숨김 여부를 설정한다. 컴퓨터활용능력 1급 B형 8/8"],"id":"2020-2-B","e":"2020 2회 B형"},{"n":56,"s":3,"a":1,"p":"다음 중 매크로 함수에 대한 설명으로 옳지 않은 것은?","c":["FindRecord 함수는 필드, 컨트롤, 속성 등의 값을 설정한다.","ApplyFilter 함수는 테이블이나 쿼리로부터 레코드를 필터링한다.","OpenReport 함수는 작성된 보고서를 호출하여 실행한다.","MessageBox 함수는 메시지 상자를 통해 경고나 알림 등의 정보를 표시한다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":57,"s":3,"a":4,"p":"다음 중 하위 폼에 대한 설명으로 옳지 않은 것은?","c":["기본 폼과 하위 폼을 연결할 필드의 데이터 형식은 같거나 호환되어야 한다.","본 폼 내에 삽입된 다른 폼을 하위 폼이라 한다.","일대다 관계가 설정되어 있는 테이블들을 효과적으로 표시하기 위해 사용된다.","‘폼 분할’ 도구를 이용하여 폼을 생성하면 하위 폼 컨트롤이 자동으로 삽입된다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":58,"s":3,"a":1,"p":"다음 중 폼의 모달 속성에 관한 설명으로 옳지 않은 것은?","c":["폼이 열려 있는 경우 다른 화면을 선택할 수 있다.","VBA 코드를 이용하여 대화 상자의 모달 속성을 지정할 수 있다.","폼이 모달 대화 상자이면 디자인 보기로 전환 후 데이터 시트 보기로 전환이 가능하다.","사용자 지정 대화 상자의 작성이 가능하다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":59,"s":3,"a":4,"p":"다음 중 보고서에 대한 설명으로 옳지 않은 것은?","c":["보고서에 포함할 필드가 모두 한 테이블에 있는 경우 해당 테이블을 레코드 원본으로 사용한다.","둘 이상의 테이블을 이용하여 보고서를 작성하는 경우 쿼리를 만들어 레코드 원본으로 사용한다.","‘보고서’ 도구를 사용하면 정보를 입력하지 않아도 바로 보고서가 생성되므로 매우 쉽고 빠르게 보고서를 만들 수 있다.","‘보고서 마법사’를 이용하는 경우 필드 선택은 여러 개의 테이블 또는 하나의 쿼리에서만 가능하며, 데이터 그룹화 및 정렬 방법을 지정할 수도 있다."],"id":"2020-2-B","e":"2020 2회 B형"},{"n":60,"s":3,"a":3,"p":"다음 중 분할 표시 폼에 대한 설명으로 옳지 않은 것은?","c":["분할 표시 폼은 [만들기] 탭의 [폼] 그룹에서 [기타 폼] - [폼 분할]을 클릭하여 만들 수 있다.","분할 표시 폼은 데이터시트 보기와 폼 보기를 동시에 표시하기 기능이며, 이 두 보기는 같은 데이터 원본에 연결되어 있어 항상 상호 동기화된다.","분할 표시 폼을 만든 후에는 컨트롤의 크기 조정은 할 수 없으나, 새로운 필드의 추가는 가능하다.","폼 속성 창의 ‘분할 표시 폼 방향’ 항목을 이용하여 폼의 위쪽, 아래쪽, 왼쪽, 오른쪽 등 데이터시트가 표시되는 위치를 설정할 수 있다. * 수고하셨습니다. 수험자 여러분의 좋은 결과를 기원합니다."],"id":"2020-2-B","e":"2020 2회 B형"}]}];
DATA.unshift(...DATA_2020);
try{home();}catch(e){}
